/**
 * What the typing case asks FloatingContainer for in wixel: the panel's own width plus the
 * avatar's gutter, so the panel still lands at INLINE_AI_PANEL_WIDTH with the avatar beside it
 * rather than eating into it, plus the container's own inline inset on both sides.
 *
 * Stated rather than left to the row to size itself: see FloatingContainer's `fixedWidth` for
 * why an intrinsic width is a poor fit for a `position: fixed` box that `shift` has to clamp.
 */
const INLINE_AI_CONTAINER_WIDTH =
  INLINE_AI_PANEL_WIDTH + ARIA_AVATAR_GUTTER + FLOATING_CONTAINER_PADDING_INLINE * 2;

const useActivePageFormat = (cardPluginConfig?: any): string | undefined => {
  const { adapter } = useContext(EditorContext);
  const storage = adapter?.tiptapEditor?.storage?.[Node_Type.CARD];
  const [format, setFormat] = React.useState<string | undefined>(
    () => storage?.activePageFormat?.name ?? cardPluginConfig?.initialPageFormat
  );

  React.useEffect(() => {
    if (!storage?.onPageFormatChange) {
      return;
    }
    const update = () => setFormat(storage.activePageFormat?.name);
    storage.onPageFormatChange.add(update);
    return () => {
      storage.onPageFormatChange.delete(update);
    };
  }, [storage]);

  return format;
};

// Config-derived values (interceptInlinePrompt, theme callbacks,
// generatingLabel) are deliberately NOT props — they are read from plugin
// config via useInlineAiPluginConfig at the point of use, so no open/reopen
// call site can forget to thread them.
export type AiModalNgProps = InlineAiAnchorProps & {
  onDone?: (result: { type: 'error' } | { type: 'done' }) => void;
  acceptByDefault?: boolean;
  headless?: boolean;
};

export const AiModalNg: React.FC<AiModalNgProps> = React.forwardRef((props, _ref) => {
  const [_invocationId] = React.useState(() => crypto.randomUUID());
  const invocationId = props.invocationId ?? _invocationId;

  const { adapter } = useContext(EditorContext);
  const { t, environment, isMobile } = useContext(RicosContext) || {};
  const pluginConfig = useInlineAiPluginConfig();

  // In the wixel environment the inline-AI panel uses a fixed width rather than one tracking
  // the text selection / editor width. The typing container is wider: it also hosts the Aria
  // avatar's gutter beside the panel (desktop only — AriaSurfaceRow renders no avatar on
  // mobile).
  const containerWidth = environment === 'wixel' ? INLINE_AI_PANEL_WIDTH : undefined;
  const typingContainerWidth =
    environment === 'wixel'
      ? isMobile
        ? INLINE_AI_PANEL_WIDTH
        : INLINE_AI_CONTAINER_WIDTH
      : undefined;

  const { state, setState, stop } = useInlineAiState(invocationId, DEFAULT_TYPING_STATE);

  // When the selection tooltip is enabled and this opening is selection-anchored (see
  // InlineAiAnchorProps), the tooltip renders the typing panel around its own Aria avatar and
  // this modal stays open as the state owner but paints nothing while typing. Nothing is
  // published for the tooltip: it calls shouldTooltipHostTyping on the same componentProps,
  // read back off the modal service — see useAnchoredInlineAiSession.
  const hostedByTooltip =
    Boolean(pluginConfig.enableSelectionTooltip) && shouldTooltipHostTyping(props, isMobile);

  React.useEffect(() => {
    if (state.type === 'closed') {
      // The undo→preview flow below closes the modal and then re-sets 'closed',
      // re-running this effect — guard so that doesn't warn.
      if (modalService.isModalOpen(INLINE_AI_MODAL_ID)) {
        modalService.closeModal(INLINE_AI_MODAL_ID);
      }

      // Preview mode is only useful when there are multiple changes to review
      // For single changes, normal undo/redo is sufficient
      const actionableMessageCount = state.messages.filter(
        m => m.type === 'insert' || m.type === 'replace'
      ).length;
      const shouldEnablePreviewMode = actionableMessageCount > 1;

      const accepted = state.messages
        .filter(messageIsAcceptable)
        .sort(orderInsertsFirst)
        .map(m => {
          // Construct position from message data (aiRegion may not be set yet)
          const position =
            m.aiRegion ??
            (m.type === 'insert'
              ? { type: 'afterNode' as const, id: m.after || undefined }
              : {
                  type: 'range' as const,
                  from: m.from,
                  to: m.to,
                  originalNodesRef: m.originalNodesRef,
                });
          return { nodes: m.nodes, position };
        });
      // wrapped in queueMicrotask to prevent flushSync issues as the
      // ReactNodeView calls it when mounting nodes
      queueMicrotask(() => {
        // Push ActionItem for undo→preview flow (only for multiple changes)
        if (shouldEnablePreviewMode) {
          // Capture the current state for the callback closures
          const storedMessages = state.messages;
          const storedChunks = state.chunks;
          const storedPrompt = state.prompt;

          // 1. Push cleanup ActionItem BEFORE AI changes (at eventCount X)
          // This fires when user undoes while in preview state (second undo)
          adapter.tiptapEditor.commands.pushActionItem(() => {
            queueMicrotask(() => {
              // Check if the inline AI modal is currently open
              const isModalOpen = modalService.isModalOpen(INLINE_AI_MODAL_ID);
              if (isModalOpen) {
                // Preview is active - close it and clean up AI regions
                adapter.tiptapEditor.commands.removeAllAiRegions();
                modalService.closeModal(INLINE_AI_MODAL_ID);
                setState({
                  type: 'closed',
                  messages: storedMessages,
                  chunks: storedChunks,
                  prompt: storedPrompt,
                });
              } else {
                // No preview active, forward the undo
                adapter.tiptapEditor.commands.undo();
              }
            });
          });

          // 2. Apply AI changes (moves eventCount to X+1)
          adapter.tiptapEditor.commands.acceptRegions(accepted);
          adapter.tiptapEditor.commands.removeAllAiRegions();

          // 3. Push preview ActionItem AFTER AI changes (at eventCount X+1)
          // This fires first when user undoes (first undo)
          adapter.tiptapEditor.commands.pushActionItem(() => {
            queueMicrotask(() => {
              // Undo the AI changes (moves eventCount to X)
              adapter.tiptapEditor.commands.undo();

              // Then trigger preview state
              setState({
                type: 'preview',
                // Clear aiRegion so useAiRegions creates fresh overlays
                messages: storedMessages.map(m => {
                  if (m.type === 'insert' || m.type === 'replace') {
                    const { aiRegion, ...rest } = m;
                    return rest as typeof m;
                  }
                  return m;
                }),
                activeMessageIndex: storedMessages.findLastIndex(m => m.type !== 'text'),
                chunks: storedChunks,
                prompt: storedPrompt,
              });

              // Re-open the modal for preview — same anchored session
              // continuing, so carry the anchor flag over.
              modalService.openModal({
                id: INLINE_AI_MODAL_ID,
                Component: AiModalNg,
                componentProps: {
                  invocationId,
                  anchorToSelection: props.anchorToSelection,
                },
                type: 'exclusive',
                layout: 'manual',
                positioning: {
                  referenceElement: getFakeReferenceElement(adapter.tiptapEditor),
                  placement: 'bottom',
                },
                returnFocusToEditor: false,
              });
            });
          });
        } else {
          // No actionable messages, just apply changes without ActionItems
          adapter.tiptapEditor.commands.acceptRegions(accepted);
          adapter.tiptapEditor.commands.removeAllAiRegions();
        }
      });

      // notify completion
      props.onDone?.({ type: 'done' });
    }

    if (state.type === 'error') {
      if (props.headless) {
        modalService.closeModal(INLINE_AI_MODAL_ID);
      }
      adapter.tiptapEditor.commands.removeAllAiRegions();
      props.onDone?.({ type: 'error' });
    }

    if (state.type === 'typing') {
      // When returning to typing (e.g., after stop in headed mode),
      // clean up any AI regions that may have been created during streaming
      queueMicrotask(() => {
        adapter.tiptapEditor.commands.removeAllAiRegions();
      });
    }
  }, [state.type]);

  const modalService = useContext(ModalServiceContext);

  const tiptapEditor = adapter.tiptapEditor;

  switch (state.type) {
    case 'typing': {
      if (hostedByTooltip) {
        // Rendered by AiSelectionTooltip (expanded mode) instead — it shares
        // this modal's typing state via InlineAiContext + invocationId, and
        // hosts the prompt panel around its own Aria avatar.
        return null;
      }
      return (
        <FloatingContainer
          {...props}
          fixedWidth={typingContainerWidth}
          state="overlay"
          editorContainer={tiptapEditor.options.element as HTMLElement}
          onClickOutside={() => setState(toClosed)}
        >
          <AriaSurfaceRow>
            <InlineAiTypingPanel invocationId={invocationId} />
          </AriaSurfaceRow>
        </FloatingContainer>
      );
    }
    case 'pending':
      if (props.headless) {
        return null;
      }
      return (
        <FloatingContainer
          {...props}
          fixedWidth={containerWidth}
          state="top"
          editorContainer={tiptapEditor.options.element as HTMLElement}
          onClickOutside={() => {}}
        >
          <div
            style={{
              display: 'flex',
              justifyContent: 'center',
              alignItems: 'center',
            }}
          >
            <Spinner onClick={() => stop({ headless: props.headless ?? false })} />
          </div>
        </FloatingContainer>
      );
    case 'streaming': {
      const aiMessages = state.messages;

      return (
        <FloatingContainer
          {...props}
          fixedWidth={containerWidth}
          state="top"
          editorContainer={tiptapEditor.options.element as HTMLElement}
          onClickOutside={() => {}}
        >
          {!props.headless && (
            <div
              style={{
                display: 'flex',
                justifyContent: 'center',
                alignItems: 'center',
              }}
            >
              <Spinner onClick={() => stop({ headless: props.headless ?? false })} />
            </div>
          )}
          <AiRegionStreams
            closeModal={() => setState(toClosed)}
            headless={props.headless}
            completed={false}
            aiMessages={aiMessages}
            activeMessageIndex={aiMessages.findLastIndex(m => m.type !== 'text')}
            setActiveMessageIndex={() => {}}
            setAiMessages={action => {
              setState(s => {
                if (s.type === 'streaming') {
                  return {
                    ...s,
                    messages: typeof action === 'function' ? action(s.messages) : action,
                  };
                } else {
                  return s;
                }
              });
            }}
            onAcceptAll={() => setState(toClosed)}
            onRejectAll={() => setState(toRejected)}
            t={t}
            generatingLabel={pluginConfig.generatingLabel}
          />
        </FloatingContainer>
      );
    }
    case 'preview': {
      // Preview state is triggered externally when 'undo' is clicked after AI application
      // Shows pager, undo/redo per item, accept all/reject all buttons
      const aiMessages = state.messages;

      const textFromTextResponse = aiMessages
        .filter(m => m.type === 'text')
        .map(m => m.text)
        .join('\n');
      const noActionMessages = !aiMessages.length || aiMessages.every(m => m.type === 'text');

      if (noActionMessages && props.headless) {
        return null;
      }
      if (noActionMessages) {
        return (
          <FloatingContainer
            {...props}
            fixedWidth={containerWidth}
            state="top"
            editorContainer={tiptapEditor.options.element as HTMLElement}
            onClickOutside={() => setState(toClosed)}
          >
            <div
              className={style.textResponseContainer}
              data-hook={INLINE_AI_TEXT_RESPONSE_CONTAINER}
            >
              {textFromTextResponse}
              <CloseButton
                size="medium"
                className={style.closeButton}
                onClick={() => setState(toClosed)}
              />
            </div>
          </FloatingContainer>
        );
      }

      return (
        <FloatingContainer
          {...props}
          fixedWidth={containerWidth}
          state="top"
          editorContainer={tiptapEditor.options.element as HTMLElement}
          onClickOutside={e => {
            // close only if clicked inside editor
            if (e.target instanceof Element && e.target.closest('.ProseMirror')) {
              setState(toClosed);
            }
          }}
        >
          <AiRegionStreams
            closeModal={() => setState(toClosed)}
            headless={false}
            completed
            aiMessages={aiMessages}
            activeMessageIndex={state.activeMessageIndex}
            setActiveMessageIndex={index => {
              setState(s => {
                if (s.type !== 'preview') {
                  return s;
                }
                return { ...s, activeMessageIndex: index };
              });
            }}
            setAiMessages={action => {
              setState(s => {
                if (s.type === 'preview') {
                  return {
                    ...s,
                    messages: typeof action === 'function' ? action(s.messages) : action,
                  };
                } else {
                  return s;
                }
              });
            }}
            onAcceptAll={() => setState(toClosed)}
            onRejectAll={() => setState(toRejected)}
            t={t}
            generatingLabel={pluginConfig.generatingLabel}
          />
        </FloatingContainer>
      );
    }
    case 'error': {
      if (props.headless) {
        return null;
      }
      return (
        <FloatingContainer
          {...props}
          fixedWidth={containerWidth}
          state="top"
          editorContainer={tiptapEditor.options.element as HTMLElement}
          onClickOutside={() => setState(toClosed)}
        >
          <div className={style.errorResponseContainer} data-hook={INLINE_AI_ERROR_CONTAINER}>
            {state.error.message}
            <CloseButton
              size="medium"
              className={style.closeButton}
              onClick={() => setState({ type: 'typing', value: state.prompt })}
            />
          </div>
        </FloatingContainer>
      );
    }
    case 'closed': {
      return null;
    }
    default: {
      logInvariant(unreachable(state));
      return <div />;
    }
  }
});

// Streaming cursor component using floating-ui for proper positioning with boundary handling.
// Reads all state from CursorContext so it can be rendered as a GlobalComponent inside the
// editor DOM, avoiding stacking context conflicts with host application shells.
export const StreamingCursor: React.FC = () => {
  const cursorCtx = useContext(CursorContext);
  const isVisible = cursorCtx?.cursorState.showCursor ?? false;
  const label = cursorCtx?.cursorState.label;
  const cursorAnchorRef = cursorCtx?.cursorAnchorRef ?? null;
  const boundary = useToolbarBoundary();
  const zIndexService = useContext(ZIndexContext);

  // Create a virtual reference element based on the shared anchor ref.
  const referenceElement = useMemo(
    () => ({
      getBoundingClientRect: () => {
        const anchor = cursorAnchorRef?.current;
        if (!anchor) {
          return new DOMRect(0, 0, 0, 0);
        }
        const anchorRect = anchor.getBoundingClientRect();
        // Return a rect centered vertically on the anchor
        return new DOMRect(anchorRect.left, anchorRect.top, 0, anchorRect.height);
      },
    }),
    [cursorAnchorRef, isVisible]
  );

  const {
    x,
    y,
    refs: { setReference, setFloating },
    strategy,
    middlewareData,
  } = useFloating({
    placement: 'right-start',
    middleware: [
      // Hide when reference element is gone or escaped boundary
      hide({ strategy: 'referenceHidden' }),
      ...(boundary ? [hide({ strategy: 'escaped', boundary })] : []),
    ],
    whileElementsMounted: (referenceEl, floatingEl, update) =>
      autoUpdate(referenceEl, floatingEl, update, {
        animationFrame: true,
      }),
  });

  useEffect(() => {
    setReference(referenceElement);
  }, [setReference, referenceElement]);

  // Hide cursor when reference element is gone or escaped boundary
  const isHidden =
    !isVisible ||
    middlewareData.hide?.referenceHidden ||
    middlewareData.hide?.escaped ||
    (x === null && y === null);

  return (
    <span
      ref={setFloating}
      className={style.streamingCursor}
      data-hook={INLINE_AI_STREAMING_CURSOR}
      style={{
        position: strategy,
        left: x ?? 0,
        top: y ?? 0,
        pointerEvents: 'none',
        display: isHidden ? 'none' : 'block',
        zIndex: zIndexService?.getZIndex('DIALOG') ?? 10,
      }}
    >
      {label && (
        <span className={style.streamingCursorFlag} data-hook={INLINE_AI_STREAMING_CURSOR_FLAG}>
          {label}
        </span>
      )}
    </span>
  );
};

/**
 * Counts the number of CARD nodes that precede the AI message's target position
 * in the editor document. This offset is needed because the modal's viewer renders
 * only the AI region's nodes, so nodeIndex starts at 0 within that subset.
 */
const getCardIndexOffset = (
  editor: Editor | undefined,
  message: AiMessageInsert | AiMessageReplace
): number => {
  if (!editor) {
    return 0;
  }
  const doc = editor.state.doc;
  const targetId = message.type === 'replace' ? message.from : message.after;

  if (!targetId) {
    return 0;
  }

  let offset = 0;
  let found = false;
  doc.descendants((node, _pos) => {
    if (found) {
      return false;
    }
    if (node.attrs.id === targetId) {
      found = true;
      // For inserts, the target is the node *after which* content is placed,
      // so if it's a CARD it should be counted as preceding the new content.
      if (message.type === 'insert' && node.type.name === 'CARD') {
        offset++;
      }
      return false;
    }
    if (node.type.name === 'CARD') {
      offset++;
      return false;
    }
  });

  return offset;
};

/**
 * Counts the number of CARD nodes in the editor document range being replaced
 * (between `from` and `to` node IDs inclusive).
 */
const getReplacedCardCount = (editor: Editor | undefined, message: AiMessageReplace): number => {
  if (!editor) {
    return 0;
  }
  const doc = editor.state.doc;

  let count = 0;
  let inRange = false;
  doc.descendants((node, _pos) => {
    if (node.attrs.id === message.from) {
      inRange = true;
    }
    if (inRange && node.type.name === 'CARD') {
      count++;
    }
    if (node.attrs.id === message.to) {
      inRange = false;
      return false;
    }
  });

  return count;
};

const AiRegionStreams: React.FC<{
  completed: boolean;
  headless?: boolean;
  aiMessages: AiMessage[];
  activeMessageIndex: number;
  setActiveMessageIndex: (index: number) => void;
  setAiMessages: (arg: React.SetStateAction<AiMessage[]>) => void;
  closeModal: () => void;
  onAcceptAll: () => void;
  onRejectAll: () => void;
  t: (key: string) => string;
  generatingLabel?: string | null;
}> = ({
  closeModal,
  aiMessages,
  setAiMessages,
  completed,
  headless,
  activeMessageIndex,
  setActiveMessageIndex,
  onAcceptAll,
  onRejectAll,
  t,
  generatingLabel,
}) => {
  useAiRegions(aiMessages, setAiMessages);
  const { adapter } = useContext(EditorContext);
  const tiptapEditor = adapter?.tiptapEditor;
  const editorPlugins = useContext(PluginsContext);
  const cardPluginConfig = editorPlugins?.getConfig(Node_Type.CARD);
  const activePageFormat = useActivePageFormat(cardPluginConfig);

  // Sync pending AI card insertions to the card extension storage so editor
  // card headers can offset their indices to account for not-yet-accepted cards.
  React.useEffect(() => {
    const storage = tiptapEditor?.storage?.[Node_Type.CARD];
    if (!storage) {
      return;
    }

    const insertions = aiMessages
      .filter(
        (m): m is AiMessageInsert | AiMessageReplace =>
          m.type !== 'text' && m.type !== 'theme' && !m.viewBefore
      )
      .map(m => {
        const newCardCount = m.nodes.filter(n => n.type === Node_Type.CARD).length;
        const replacedCardCount = m.type === 'replace' ? getReplacedCardCount(tiptapEditor, m) : 0;
        const netCount = newCardCount - replacedCardCount;
        if (netCount === 0) {
          return null;
        }
        const afterCardIndex = getCardIndexOffset(tiptapEditor, m);
        return { afterCardIndex, count: netCount };
      })
      .filter((v): v is NonNullable<typeof v> => v !== null);

    storage.pendingCardInsertions = insertions;
    storage.onPendingCardInsertionsChange.forEach((cb: () => void) => cb());

    return () => {
      storage.pendingCardInsertions = [];
      storage.onPendingCardInsertionsChange.forEach((cb: () => void) => cb());
    };
  }, [aiMessages, tiptapEditor]);

  const aiMessagesRef = React.useRef<AiMessage[]>(aiMessages);
  aiMessagesRef.current = aiMessages;

  // Find the last streaming (not completed) message for cursor positioning
  const lastStreamingMessageIndex = React.useMemo(() => {
    if (completed) {
      return -1;
    }
    for (let i = aiMessages.length - 1; i >= 0; i--) {
      const msg = aiMessages[i];
      if (msg && msg.type !== 'text' && msg.type !== 'theme' && !msg.completed) {
        return i;
      }
    }
    return -1;
  }, [aiMessages, completed]);

  const showCursor = !completed && lastStreamingMessageIndex !== -1;

  // Sync cursor visibility into shared CursorContext so StreamingCursor (rendered as a
  // GlobalComponent in the editor DOM) can read it without stacking context issues.
  const cursorCtx = useContext(CursorContext);
  const resolvedLabel = generatingLabel !== undefined ? generatingLabel : t('InlineAi_Generating');
  React.useEffect(() => {
    cursorCtx?.setCursorState({ showCursor, label: resolvedLabel });
    return () => {
      cursorCtx?.setCursorState({ showCursor: false, label: null });
    };
  }, [showCursor, resolvedLabel]);

  const actionableMessageCount = aiMessages.filter(m => m.type !== 'text').length;

  const activeMessage = aiMessages[activeMessageIndex] as
    | AiMessageInsert
    | AiMessageReplace
    | undefined;

  const pagerAPI = getPagerAPI(
    aiMessages,
    activeMessageIndex,
    setActiveMessageIndex,
    setAiMessages
  );

  return (
    <>
      <div className={style.bottomContainer}>
        {completed && activeMessage && !headless && (
          <div className={style.bottomControls}>
            {actionableMessageCount > 1 && (
              <>
                <Pager
                  current={activeMessageIndex}
                  total={actionableMessageCount}
                  onPrev={() => {
                    pagerAPI.onPrev();
                  }}
                  onNext={() => {
                    pagerAPI.onNext();
                  }}
                />
                <VerticalDivider />
                <Button
                  className="ai-region-button"
                  size="small"
                  priority="secondary"
                  prefixIcon={activeMessage.viewBefore ? <RedoSmall /> : <UndoSmall />}
                  onClick={() => {
                    pagerAPI.toggleUndo();
                  }}
                  dataHook={INLINE_AI_BEFORE_AFTER_BUTTON}
                >
                  {activeMessage.viewBefore ? t('InlineAi_After') : t('InlineAi_Before')}
                </Button>
              </>
            )}
            <Button
              className="ai-region-button"
              size="small"
              priority="secondary"
              onClick={onAcceptAll}
              dataHook={INLINE_AI_ACCEPT_ALL_BUTTON}
            >
              {t('InlineAi_AcceptAll')}
            </Button>
            <Button
              className="ai-region-button"
              size="small"
              priority="secondary"
              onClick={onRejectAll}
              dataHook={INLINE_AI_REJECT_ALL_BUTTON}
            >
              {t('InlineAi_RejectAll')}
            </Button>
          </div>
        )}
        {aiMessages.map((message, index) => {
          if (!message) {
            return null;
          }
          if (message.type === 'text' || message.type === 'theme') {
            return null;
          }
          if (!message.aiRegion) {
            return null;
          }
          const overlay = message.aiRegion.overlay;
          if (!overlay) {
            return null;
          }
          return ReactDOM.createPortal(
            <div
              className="ricos-ai-region-viewer"
              style={{ position: 'relative' }}
              data-hook={`${INLINE_AI_AI_REGION_VIEWER}${
                completed ? ` ${INLINE_AI_AI_REGION_COMPLETED}` : ''
              }`}
            >
              <Viewer
                nodes={
                  !message.viewBefore
                    ? message.nodes
                    : message.type === 'replace'
                      ? message.originalNodesRef.current || []
                      : []
                }
                isRoot={message.isRootLevel}
                isStreaming={!completed}
                isCompleted={!!message.completed}
                isActive={activeMessageIndex === index && pagerAPI.total > 1}
                onHover={() => {
                  if (!completed) {
                    return;
                  }
                  if (activeMessageIndex !== index) {
                    setActiveMessageIndex(index);
                  }
                }}
                onClick={() => {
                  if (!completed) {
                    return;
                  }
                  closeModal();
                }}
                cardPluginConfig={cardPluginConfig}
                activePageFormat={activePageFormat}
                cardIndexOffset={getCardIndexOffset(tiptapEditor, message)}
              />

              <div
                style={{
                  display: 'flex',
                  gap: '8px',
                  marginTop: '8px',
                  position: 'absolute',
                  left: '0',
                  right: '0',
                  zIndex: 1000,
                }}
              />
            </div>,
            overlay
          );
        })}
      </div>
    </>
  );
};

const useAiRegions = (
  aiMessages: AiMessage[],
  setAiMessages: (arg: React.SetStateAction<AiMessage[]>) => void
): void => {
  const commands = useContext(EditorContext).adapter.tiptapEditor.commands;

  React.useEffect(() => {
    const aiMessagesWithoutRegions = aiMessages.filter(
      m => m.type !== 'text' && m.type !== 'theme' && !m.aiRegion
    );

    if (aiMessagesWithoutRegions.length === 0) {
      return;
    }
    setAiMessages((aiMessages: AiMessage[]): AiMessage[] => {
      const newRegions = [] as AiRegion[];
      const newAiMessages = aiMessages.map((m): AiMessage => {
        if (m.type === 'text' || m.type === 'theme' || m.aiRegion) {
          return m;
        }
        if (m.type === 'insert') {
          const aiRegion = {
            type: 'afterNode' as const,
            id: m.after || undefined,
            overlay: document.createElement('div'),
          };
          newRegions.push(aiRegion);
          return { ...m, aiRegion };
        }
        if (m.type === 'replace') {
          const aiRegion = {
            type: 'range' as const,
            from: m.from,
            to: m.to,
            overlay: document.createElement('div'),
            originalNodesRef: m.originalNodesRef,
          };
          newRegions.push(aiRegion);
          return { ...m, aiRegion };
        }
        logInvariant(unreachable(m));
        return m;
      });
      newRegions.length && commands.addAiRegions(newRegions);
      return newAiMessages;
    });
  }, [aiMessages, setAiMessages]);
};

// During streaming, patch collapsible lists to:
// 1. Expand all items so users can see the content being generated
// 2. Add empty body if only title exists (otherwise the item won't render)
const patchCollapsibleListsDuringStreaming = (nodes: RicosDocumentNode[]): RicosDocumentNode[] => {
  return nodes.map(node => {
    // If this is a collapsible list, set initialExpandedItems to ALL
    if (node.type === 'COLLAPSIBLE_LIST') {
      return {
        ...node,
        collapsibleListData: {
          ...node.collapsibleListData,
          initialExpandedItems: CollapsibleListData_InitialExpandedItems.ALL,
        },
        nodes: node.nodes ? patchCollapsibleListsDuringStreaming(node.nodes) : node.nodes,
      } as RicosDocumentNode;
    }

    // If this is a collapsible item, ensure it has both title and body
    if (node.type === 'COLLAPSIBLE_ITEM') {
      const children = node.nodes ?? [];
      const hasTitle = children.some(child => child.type === 'COLLAPSIBLE_ITEM_TITLE');
      const hasBody = children.some(child => child.type === 'COLLAPSIBLE_ITEM_BODY');

      // If there's a title but no body, add an empty body
      if (hasTitle && !hasBody) {
        const emptyBody: RicosDocumentNode = {
          type: 'COLLAPSIBLE_ITEM_BODY',
          id: `${node.id}-body`,
          nodes: [
            {
              type: 'PARAGRAPH',
              id: `${node.id}-body-p`,
              nodes: [],
            } as RicosDocumentNode,
          ],
        } as RicosDocumentNode;

        return {
          ...node,
          nodes: [...patchCollapsibleListsDuringStreaming(children), emptyBody],
        } as RicosDocumentNode;
      }

      return {
        ...node,
        nodes: children.length > 0 ? patchCollapsibleListsDuringStreaming(children) : children,
      } as RicosDocumentNode;
    }

    // Recursively process child nodes
    if (node.nodes && node.nodes.length > 0) {
      return {
        ...node,
        nodes: patchCollapsibleListsDuringStreaming(node.nodes),
      } as RicosDocumentNode;
    }

    return node;
  });
};

const Viewer = React.memo(
  ({
    nodes,
    isStreaming,
    isCompleted,
    isActive,
    onClick,
    onHover,
    isRoot,
    onContainerRef,
    cardPluginConfig,
    activePageFormat,
    cardIndexOffset,
  }: {
    nodes: RicosDocumentNode[];
    isStreaming: boolean;
    isCompleted: boolean;
    isActive: boolean;
    onClick: () => void;
    onHover: () => void;
    isRoot: boolean;
    onContainerRef?: (ref: HTMLDivElement | null) => void;
    cardPluginConfig?: any;
    activePageFormat?: string;
    cardIndexOffset?: number;
  }) => {
    const containerRef = React.useRef<HTMLDivElement>(null);

    React.useEffect(() => {
      injectCss();
      imageInject();
    }, []);

    // Register container ref with parent for cursor positioning
    React.useEffect(() => {
      onContainerRef?.(containerRef.current);
      return () => onContainerRef?.(null);
    }, [onContainerRef]);

    const nodesWithCursor =
      isStreaming && !isCompleted
        ? appendNodeToLastNonEmptyTextContainer(nodes, {
            type: 'CURSOR',
          } as unknown as RicosDocumentNode).nodes
        : nodes;

    // During streaming, patch collapsible lists to expand all items and add missing bodies
    const nodesWithPatchedCollapsibleLists =
      isStreaming && !isCompleted
        ? patchCollapsibleListsDuringStreaming(nodesWithCursor)
        : nodesWithCursor;

    const content = { nodes: nodesWithPatchedCollapsibleLists } as RichContent;

    const { theme } = React.useContext(RicosContext);
    const helpers = useEditorProp(p => p.helpers);
    const instance = useEditorProp(p => p.instance);
    return (
      <ErrorBoundary retryProp={content}>
        <div
          ref={containerRef}
          style={{
            // backgroundColor: isActive ? '#A8CAFF' : '#E7F0FF',
            background: !isStreaming ? (isActive ? bgActive : bgDefault) : undefined,
            position: 'relative',
          }}
        >
          <RicosViewer
            theme={{
              ...theme,
              customStyles: omitKeys(theme.customStyles, ['container']),
              breakout: isRoot ? theme?.breakout : undefined,
            }}
            plugins={[
              {
                config: {},
                type: 'html_placeholder',
                // @ts-ignore
                nodeViewRenderers: {
                  EXTERNAL: Placeholder,
                },
              },
              {
                config: {},
                type: 'cursor_placeholder',
                // @ts-ignore - CURSOR is a custom node type for inline AI streaming
                nodeViewRenderers: { CURSOR: CursorPlaceholder },
              },
              ...quickStartViewerPlugins(),
              pluginCardViewer({
                mode: 'editor',
                renderCardHeader: cardPluginConfig.renderCardHeader,
                pageFormat: activePageFormat,
                cardIndexOffset,
              }),
            ]}
            content={content as unknown as RichContent}
            helpers={helpers}
            instance={instance}
          />
          <button
            type="button"
            className="ai-region-button"
            data-hook={INLINE_AI_AI_REGION_ACCEPT_BUTTON}
            style={{
              position: 'absolute',
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              opacity: 0,
              zIndex: 10,
              cursor: 'wait',
            }}
            onClick={onClick}
            onMouseEnter={onHover}
          />
        </div>
      </ErrorBoundary>
    );
  }
);

// Recursively find and append cursor to the last non-empty text container
// Returns { nodes, appended } where appended indicates if cursor was added
const appendNodeToLastNonEmptyTextContainer = (
  nodes: RicosDocumentNode[],
  appendedNode: RicosDocumentNode
): { nodes: RicosDocumentNode[]; appended: boolean } => {
  // Try nodes from last to first to find a non-empty text container
  for (let i = nodes.length - 1; i >= 0; i--) {
    const node = nodes[i];
    if (!node) {
      continue;
    }

    if (isTextContainer(node.type)) {
      // Found a text container - only append if it has content
      if (node.nodes?.length) {
        return {
          nodes: [
            ...nodes.slice(0, i),
            {
              ...node,
              nodes: [...(node.nodes ?? []), appendedNode],
            } as RicosDocumentNode,
            ...nodes.slice(i + 1),
          ],
          appended: true,
        };
      }
      // Empty text container - continue to previous sibling
      continue;
    }

    // Not a text container - try to recurse into its children
    if (node.nodes?.length) {
      const result = appendNodeToLastNonEmptyTextContainer(node.nodes, appendedNode);
      if (result.appended) {
        return {
          nodes: [
            ...nodes.slice(0, i),
            { ...node, nodes: result.nodes } as RicosDocumentNode,
            ...nodes.slice(i + 1),
          ],
          appended: true,
        };
      }
    }
    // Recursion didn't find a non-empty text container - continue to previous sibling
  }

  // No non-empty text container found
  return { nodes, appended: false };
};

// CursorPlaceholder uses the shared ref from CursorContext so StreamingCursor can position relative to it
const CursorPlaceholder: React.FC = () => {
  const cursorAnchorRef = React.useContext(CursorContext)?.cursorAnchorRef ?? null;
  return (
    <span
      ref={cursorAnchorRef}
      style={{
        display: 'inline-block',
        width: 0,
        height: '1em', // Inherits the font size of the parent, matching line height
        verticalAlign: 'middle',
      }}
    />
  );
};

const messageIsAcceptable = (m: AiMessage): m is AiMessageReplace | AiMessageInsert =>
  (m.type === 'insert' || m.type === 'replace') && !m.viewBefore;

const VerticalDivider: React.FC = () => (
  <div
    style={{
      width: '1px',
      backgroundColor: '#DFE5EB',
      height: '100%',
    }}
  />
);

const Placeholder: React.FC = ({ node, nodeIndex, NodeViewContainer }: any) => {
  const innerNode: RicosDocumentNode = node.externalData;
  return (
    <NodeViewContainer node={innerNode} nodeIndex={nodeIndex}>
      {innerNode.type === 'HTML' ? (
        <HtmlPlaceholder node={innerNode} />
      ) : innerNode.type === 'IMAGE' ? (
        <ImagePlaceholder node={innerNode} />
      ) : (
        <PendingWidgetPlaceholder node={node} />
      )}
    </NodeViewContainer>
  );
};

// Ensure all 'insert' operations are applied before 'replace' operations
// so that insert IDs remain consistent and unaffected by replacements.
const orderInsertsFirst = (
  a: AiMessageInsert | AiMessageReplace,
  b: AiMessageInsert | AiMessageReplace
) => {
  if (a.type === b.type) {
    return 0;
  }
  return a.type === 'insert' ? -1 : 1;
};

// Helper to create a reference element for positioning the modal
const getFakeReferenceElement = (
  editor: Editor
): { getBoundingClientRect: () => DOMRect; focus: () => void } => {
  const { view } = editor;
  const { from, to } = view.state.selection;

  const getRect = (): DOMRect => {
    if (from === to) {
      const coords = view.coordsAtPos(from);
      return new DOMRect(coords.left, coords.top, 0, coords.bottom - coords.top);
    }
    const start = view.coordsAtPos(from);
    const end = view.coordsAtPos(to);
    return new DOMRect(
      Math.min(start.left, end.left),
      start.top,
      Math.abs(end.left - start.left),
      end.bottom - start.top
    );
  };

  return {
    getBoundingClientRect: getRect,
    focus: () => view.focus(),
  };
};

// When rejecting, set all messages' viewBefore to true so they show original content
// This effectively rejects all AI changes
const toRejected: (s: InlineAiState) => InlineAiState = s => {
  if (s.type === 'closed') {
    return s;
  }
  const messages = 'messages' in s ? s.messages : [];
  const rejectedMessages = messages.map(m => {
    if (m.type === 'insert' || m.type === 'replace') {
      return { ...m, viewBefore: true };
    }
    return m;
  });
  return {
    type: 'closed',
    messages: rejectedMessages,
    chunks: 'chunks' in s ? s.chunks : [],
    prompt: 'prompt' in s ? s.prompt : '',
  };
};

const bgActive = 'hsla(0, 10%, 80%, 0.6)';
const bgDefault = 'hsla(0, 10%, 80%, 0.4)';
