import type { RicosDocumentNode } from './../ricos-schema/next-schema/index.js';
import { aiRegionPluginKey } from './../_shared/ai-region-plugin-key.js';
import { logInvariant } from './../_shared/log-invariant.js';
import type { Transaction } from './../tiptap/pm/state.js';
import { Plugin } from './../tiptap/pm/state.js';
import { Decoration, DecorationSet } from './../tiptap/pm/view.js';
import type { NodeWithPos } from './../tiptap/types.js';
import { isDefined } from './../wix-rich-content-common/index.js';
import { createRicosFunctionalExtension } from './../tiptap-extensions/index.js';

const AI_REGION_RANGE_CLASS = 'ricos-ai-region';

export type RangeAiRegion = {
  type: 'range';
  from?: string;
  to?: string;
  excluded?: boolean;
  overlay?: HTMLElement;
  originalNodesRef: { current?: RicosDocumentNode[] };
};

export type AfterAiRegion = {
  type: 'afterNode';
  // when no id is provided, the Ai Region will be placed at the beginning of the document
  id?: string;
  overlay?: HTMLElement;
};

export type AiRegion = RangeAiRegion | AfterAiRegion;

export type DocumentChange = { nodes: RicosDocumentNode[]; position: AiRegion };

declare module './../tiptap/core' {
  interface Commands<ReturnType> {
    aiRegion: {
      addAiRegions: (regions: AiRegion[]) => ReturnType;
      syncAiRegions: (regions: AiRegion[]) => ReturnType;
      removeAiRegions: (regions: AiRegion[]) => ReturnType;
      removeAllAiRegions: () => ReturnType;
      acceptRegions: (changes: DocumentChange[]) => ReturnType;
      // injectNodes: (args: DocumentChange[], revert: { changes?: DocumentChange[] }) => ReturnType;
      // clear: () => ReturnType;
    };
  }
}
type PmPluginState = { regionList: AiRegion[]; decorations: DecorationSet };

export const aiRegion = createRicosFunctionalExtension({
  type: 'extension',
  groups: [],
  name: 'ai-region',

  createExtensionConfig({ services }) {
    const pmPlugin = new Plugin({
      key: aiRegionPluginKey,
      state: {
        init(): PmPluginState {
          return {
            regionList: [],
            decorations: DecorationSet.empty,
          };
        },
        apply(tr, state): PmPluginState {
          const meta = tr.getMeta(pmPlugin);

          const regionList = meta?.addRegionList?.length
            ? [...state.regionList, ...meta.addRegionList]
            : meta?.syncRegionList?.length
              ? meta.syncRegionList
              : meta?.removeRegionList?.length
                ? state.regionList.filter(r => !meta.removeRegionList.includes(r))
                : meta?.removeAllRegions && state.regionList.length
                  ? []
                  : state.regionList;

          if (state.regionList === regionList) {
            return { ...state, decorations: state.decorations.map(tr.mapping, tr.doc) };
          }

          const nodeWithPosListRange: {
            nodesWithPos: NodeWithPos[];
            posAfter: number;
            overlay?: HTMLElement;
          }[] = (regionList as AiRegion[])
            .filter((s: AiRegion): s is RangeAiRegion => s.type === 'range')
            .map(s => {
              const { from, to, excluded } = s;
              const fromNode = from
                ? excluded
                  ? findNodeSiblingAfterNodeId(tr, from)
                  : findNodeById(tr, from)
                : getFirstNode(tr);
              const toNode = to
                ? excluded
                  ? findNodeSiblingBeforeNodeId(tr, to)
                  : findNodeById(tr, to)
                : getLastNode(tr);
              if (!fromNode) {
                console.error(`Ai Region: Node with id ${from} not found`);
                return undefined;
              }
              if (!toNode) {
                console.error(`Ai Region: Node with id ${to} not found`);
                return undefined;
              }
              const parentFromNode = tr.doc.resolve(fromNode.pos).parent;
              const parentToNode = tr.doc.resolve(toNode.pos).parent;
              if (parentFromNode !== parentToNode) {
                console.error(`Ai Region: Nodes with ids ${from} and ${to} are not siblings`);
                return undefined;
              }
              const allNodesInRegionRange: NodeWithPos[] = [];
              tr.doc.nodesBetween(
                fromNode.pos,
                toNode.pos + toNode.node.nodeSize,
                (node, pos, parent) => {
                  if (parent === parentFromNode) {
                    allNodesInRegionRange.push({ node, pos });
                    return false;
                  }
                }
              );
              const posAfter = toNode.pos + toNode.node.nodeSize;

              const originalRicosNodes = allNodesInRegionRange.map(nodeWithPos =>
                services.converters.fromPmNode(nodeWithPos.node.toJSON())
              ) as RicosDocumentNode[];

              // @TODO: Remove this hacky mutation
              s.originalNodesRef.current = originalRicosNodes;

              return {
                nodesWithPos: allNodesInRegionRange,
                overlay: s.overlay,
                posAfter,
              };
            })
            .filter(isDefined);

          const posListWithAfter: { posAfter: number; overlay?: HTMLElement }[] = regionList
            .filter((s: AiRegion): s is AfterAiRegion => s.type === 'afterNode')
            .map((s: AfterAiRegion) => {
              if (!s.id) {
                return { posAfter: 0, overlay: s.overlay };
              }
              const node = findNodeById(tr, s.id);
              if (!node) {
                console.error(`Ai Region: Node with id ${s.id} not found`);
                return undefined;
              }
              return { posAfter: node.pos + node.node.nodeSize, overlay: s.overlay };
            })
            .filter(isDefined);

          let decorations = DecorationSet.empty;

          nodeWithPosListRange.forEach(({ nodesWithPos: nodeWithPosListRange }) => {
            for (const nodeWithPos of nodeWithPosListRange) {
              const { node, pos } = nodeWithPos;
              decorations = decorations.add(tr.doc, [
                Decoration.node(pos, pos + node.nodeSize, {
                  class: AI_REGION_RANGE_CLASS,
                }),
              ]);
            }
          });

          for (const pos of [...nodeWithPosListRange, ...posListWithAfter]) {
            if (!pos.overlay) {
              continue;
            }
            decorations = decorations.add(tr.doc, [
              Decoration.widget(pos.posAfter, (_view, _getPos) => {
                return pos.overlay!;
              }),
            ]);
          }

          return {
            regionList,
            decorations,
          };
        },
      },
      props: {
        decorations(state) {
          return this?.getState(state)?.decorations;
        },
      },
    });
    return {
      name: this.name,

      addCommands() {
        return {
          acceptRegions:
            (nodesAndPositions: DocumentChange[]) =>
            ({ tr, editor }) => {
              nodesAndPositions.forEach(({ nodes, position }) => {
                const pmJsonNodes = nodes.map(node => services.converters.toPmNode(node as any));
                const pmNodes = pmJsonNodes.map(editor.schema.nodeFromJSON);
                switch (position.type) {
                  case 'range': {
                    const firstNode = position.from
                      ? position.excluded
                        ? findNodeSiblingAfterNodeId(tr, position.from)
                        : findNodeById(tr, position.from)
                      : getFirstNode(tr);
                    const lastNode = position.to
                      ? position.excluded
                        ? findNodeSiblingBeforeNodeId(tr, position.to)
                        : findNodeById(tr, position.to)
                      : getLastNode(tr);
                    if (!firstNode) {
                      console.error(`Ai Region: Node with id ${position.from} not found`);
                      return;
                    }
                    if (!lastNode) {
                      console.error(`Ai Region: Node with id ${position.to} not found`);
                      return;
                    }

                    tr.replaceWith(firstNode.pos, lastNode.pos + lastNode.node.nodeSize, pmNodes);
                    tr.setMeta('allowTextReplace', true);
                    return;
                  }
                  case 'afterNode': {
                    if (!position.id) {
                      tr.insert(0, pmNodes);
                      return;
                    }
                    const nodeWithPos = findNodeById(tr, position.id);

                    if (!nodeWithPos) {
                      console.error(`Ai Region: Node with id ${position.id} not found`);
                      return;
                    }
                    tr.insert(nodeWithPos.pos + nodeWithPos.node.nodeSize, pmNodes);
                    tr.setMeta('allowTextReplace', true);

                    return;
                  }
                  default:
                    logInvariant(new Error('Invalid position type when injecting'));
                }
              });
              tr.setMeta(pmPlugin, {
                removeRegionList: nodesAndPositions.map(({ position }) => position),
              });
              return true;
            },
          addAiRegions:
            (regionList: AiRegion[]) =>
            ({ tr, dispatch, view }) => {
              const firstNodeId =
                regionList[0]?.type === 'range' ? regionList[0].from : regionList[0]?.id;
              if (dispatch) {
                tr.setMeta(pmPlugin, {
                  addRegionList: regionList,
                });
                if (firstNodeId) {
                  if (firstNodeId === 'START') {
                    view.dom.scrollIntoView({ behavior: 'smooth', block: 'center' });
                  }
                  const nodeWithPos = findNodeById(tr, firstNodeId);
                  if (nodeWithPos) {
                    queueMicrotask(() => {
                      const { pos: _pos } = nodeWithPos;
                      const dom = regionList[0]?.overlay; //view.nodeDOM(pos) as HTMLElement;
                      if (dom) {
                        dom.scrollIntoView({ behavior: 'smooth', block: 'center' });
                      }
                    });
                  }
                }
              }
              return true;
            },

          syncAiRegions:
            (regionList: AiRegion[]) =>
            ({ tr, dispatch }) => {
              if (dispatch) {
                tr.setMeta(pmPlugin, {
                  syncRegionList: regionList,
                });
              }
              return true;
            },

          removeAllAiRegions:
            () =>
            ({ tr, dispatch }) => {
              if (dispatch) {
                tr.setMeta(pmPlugin, {
                  removeAllRegions: true,
                });
              }
              return true;
            },
          removeAiRegions:
            (regionList: AiRegion[]) =>
            ({ tr, dispatch }) => {
              if (dispatch) {
                tr.setMeta(pmPlugin, {
                  removeRegionList: regionList,
                });
              }
              return true;
            },
        };
      },

      addProseMirrorPlugins() {
        return [pmPlugin];
      },
    };
  },
});

const findNodeSiblingAfterNodeId = (tr: Transaction, id: string): NodeWithPos | undefined => {
  const nodesWithPos: NodeWithPos[] = [];
  tr.doc.descendants((child, pos, parent) => {
    if (child.attrs.id === id) {
      const afterChild = parent?.childAfter(pos + child.nodeSize);

      if (afterChild?.node) {
        const afterNode = findNodeById(tr, afterChild.node.attrs.id);
        if (afterNode) {
          nodesWithPos.push(afterNode);
        }
        return false;
      }
    }
  });
  const nodeWithPos = nodesWithPos[0];
  if (!nodeWithPos) {
    return undefined;
  }
  return nodeWithPos;
};

const findNodeSiblingBeforeNodeId = (tr: Transaction, id: string): NodeWithPos | undefined => {
  const nodesWithPos: NodeWithPos[] = [];
  tr.doc.descendants((child, pos, parent, index) => {
    if (child.attrs.id === id) {
      const beforeSiblingIndex = Math.max(index - 1, 0);
      const beforeChild = parent?.maybeChild(beforeSiblingIndex);

      if (beforeChild) {
        const beforeNode = findNodeById(tr, beforeChild.attrs.id);
        if (beforeNode) {
          nodesWithPos.push(beforeNode);
        }
        return false;
      }
    }
  });
  const nodeWithPos = nodesWithPos[0];
  if (!nodeWithPos) {
    return undefined;
  }
  return nodeWithPos;
};

const findNodeById = (tr: Transaction, id: string): NodeWithPos | undefined => {
  const nodesWithPos: NodeWithPos[] = [];
  tr.doc.descendants((child, pos) => {
    if (child.attrs.id === id) {
      nodesWithPos.push({
        node: child,
        pos,
      });
      return false;
    }
  });
  const nodeWithPos = nodesWithPos[0];
  if (!nodeWithPos) {
    return undefined;
  }
  const parent = tr.doc.resolve(nodeWithPos.pos).parent;
  if (parent.type.name === 'FIGURE' && nodeWithPos.node.type.name !== 'CAPTION') {
    return { node: parent, pos: nodeWithPos.pos - 1 };
  }
  return nodeWithPos;
};

const getFirstNode = (tr: Transaction): NodeWithPos | undefined => {
  const firstNode = tr.doc.content.firstChild;
  if (!firstNode) {
    return undefined;
  }
  return { node: firstNode, pos: 0 };
};

const getLastNode = (tr: Transaction): NodeWithPos | undefined => {
  const lastNode = tr.doc.content.lastChild;
  if (!lastNode) {
    return undefined;
  }
  return { node: lastNode, pos: tr.doc.content.size - lastNode.nodeSize };
};
