import type { ShiftOptions, VirtualElement } from '@floating-ui/react-dom';
import { flip, hide, limitShift, offset, shift, useFloating } from '@floating-ui/react-dom';
import classNames from 'classnames';
import React, {
  useCallback,
  useContext,
  useEffect,
  useLayoutEffect,
  useMemo,
  useState,
} from 'react';
import ReactDOM from 'react-dom';

import { EditorContext } from './../ricos-context/editor-context.js';
import { ModalServiceContext, RicosContext, ZIndexContext } from './../ricos-context/index.js';
import { useSelection } from './../ricos-context/selection-context.js';
import {
  getIsAnyModalOpenByIdPrefix,
  useModalState,
} from './../ricos-modals/modal-service-provider.js';
import { FocusManager } from './../_shared/focus-manager/focus-manager.js';
import { getWixelShiftPadding } from './../_shared/get-wixel-shift-padding.js';
import { useAnimationPausedAutoUpdate } from './../_shared/node-animation/use-animation-paused-auto-update.js';
// Using standard posToDOMRect from @tiptap/core (not the custom one from _shared)
// because the tooltip should position relative to the actual selection bounds,
// not the full editor width like the AI modal does.
import { posToDOMRect } from './../tiptap/index.js';
import { isTextSelection } from './../editor-common/index.js';
import { AI_WIDGET_MODAL_ID_PREFIX } from './../plugin-html/consts.js';
import { useToolbarBoundary } from './../toolbars-v3/toolbar-boundary.js';
import { ClickOutside, UiComponentsProvider } from './../ui-components/index.js';

import style from './ai-selection-tooltip-scss.js';
import { AriaAvatarIcon } from './aria-avatar-icon.js';
import { INLINE_AI_SELECTION_TOOLTIP } from './data-hooks.js';
import { useAnchoredInlineAiSession } from './inline-ai-context-provider.js';
import { openInlineAIModal } from './open-inline-ai-modal.js';
import { INLINE_AI_PANEL_WIDTH, toSelectionKey } from './types.js';
import { InlineAiTypingPanel } from './typing-panel.js';

const getShiftOptions = (
  environment: string | undefined,
  boundary: Element | null
): ShiftOptions => {
  if (environment === 'wixel') {
    return getWixelShiftPadding();
  }
  return boundary ? { boundary } : { padding: 8 };
};

/** Fully expanded plateau before collapse (snap open each selection; only shut animates). */
const HOLD_EXPANDED_MS = 500;

// Stable identity: ClickOutside's effect re-registers its document listeners
// whenever its handler prop changes.
const NOOP = () => {};

/** The pill's own distance from the selection, re-applied by the raw-selection fallback. */
const SELECTION_OFFSET = 8;

/** Frozen positioning for the expanded prompt, captured once when it opens. */
type ExpandedAnchor = {
  /** Side of the selection the pill icon sat on — decides the grow direction. */
  side: 'top' | 'bottom';
  /** 0 when anchored to the measured pill box (which already carries the offset). */
  offset: number;
  reference: VirtualElement;
};

// Captures where the pill (and its Aria avatar) actually is on screen when the
// prompt opens. Anchoring to the pill box — not the raw selection rect — matters
// because the collapsed pill may have been flipped below the selection, or
// vertically shifted by wixel's chrome padding; re-deriving the expanded
// position from the selection would teleport the prompt to the other side of
// it, away from the avatar the user just engaged. The anchor still tracks
// document scroll: it is stored as a fixed offset from the selection rect,
// which posToDOMRect re-reads every animation frame.
const createExpandedAnchor = (
  selectionReference: VirtualElement,
  pillElement: HTMLElement | null
): ExpandedAnchor => {
  const selectionRect = selectionReference.getBoundingClientRect();
  const pillRect = pillElement?.getBoundingClientRect();
  // A zero-size rect means the pill wasn't on screen when the prompt opened
  // (e.g. quick-actions flows over an empty cursor) — fall back to anchoring
  // above the selection rect itself.
  if (!pillRect || (pillRect.width === 0 && pillRect.height === 0)) {
    return { side: 'top', offset: SELECTION_OFFSET, reference: selectionReference };
  }
  const side = pillRect.top >= selectionRect.bottom ? 'bottom' : 'top';
  // The anchor line is the pill edge the avatar stays glued to: the pill's
  // bottom when the panel opens above it (growing upward), its top when the
  // pill was flipped below (growing downward).
  const anchorX = pillRect.left - selectionRect.left;
  const anchorY = (side === 'bottom' ? pillRect.top : pillRect.bottom) - selectionRect.top;
  // Carrying the pill's width lets the 'start' alignment resolve to the
  // correct edge under RTL (where 'start' is the right edge).
  const pillWidth = pillRect.width;
  return {
    side,
    offset: 0,
    reference: {
      getBoundingClientRect: () => {
        const live = selectionReference.getBoundingClientRect();
        return new DOMRect(live.left + anchorX, live.top + anchorY, pillWidth, 0);
      },
    },
  };
};

export const AiSelectionTooltip: React.FC = () => {
  const editorContext = useContext(EditorContext);
  const ricosContext = useContext(RicosContext);
  const modalService = useContext(ModalServiceContext);
  const zIndexService = useContext(ZIndexContext);
  const boundary = useToolbarBoundary();
  const { selection } = useSelection();
  // The HTML AI widget's floating prompt and this tooltip must never be shown together.
  const isAiWidgetModalOpen = useModalState(getIsAnyModalOpenByIdPrefix(AI_WIDGET_MODAL_ID_PREFIX));

  const tiptapEditor = editorContext?.adapter?.tiptapEditor;
  const t = ricosContext?.t;
  const portal = ricosContext?.portal;
  const environment = ricosContext?.environment;
  const isMobile = ricosContext?.isMobile;
  const jsdomMode = ricosContext?.jsdomMode;
  const tooltipLabel = t?.('InlineAi_SelectionTooltip') ?? 'Press "space" to edit with AI';

  // While the inline-AI modal is open for a selection-anchored flow in its
  // typing state, the modal paints nothing and this tooltip expands in place
  // into the prompt input — around the SAME mounted Aria avatar, so the avatar
  // never remounts (its show() fade would otherwise replay). AiModalNg makes
  // that call and publishes it; `expanded` and `sessionLive` come from one
  // store snapshot, so they can never disagree and strand the box unmounted for
  // a commit. See useAnchoredInlineAiSession.
  const {
    invocationId,
    expanded,
    sessionLive,
    dismiss: dismissTyping,
    submittedSelection,
    clearSubmittedSelection,
  } = useAnchoredInlineAiSession();

  const selectionKey = selection ? toSelectionKey(selection) : null;

  // Compute visibility based on selection
  const showTooltip = useMemo(() => {
    if (!tiptapEditor || !selection || isMobile) {
      return false;
    }

    if (selection.empty) {
      return false;
    }

    if (sessionLive || isAiWidgetModalOpen) {
      return false;
    }

    // A prompt has already been submitted over exactly this selection — don't
    // re-offer it there.
    if (submittedSelection && submittedSelection === selectionKey) {
      return false;
    }

    // Check for text selection with actual text content
    if (isTextSelection(selection)) {
      let hasText = false;
      tiptapEditor.state.doc.nodesBetween(selection.from, selection.to, node => {
        if (node.type.name === 'text' && node.text !== '') {
          hasText = true;
          return false;
        }
      });
      return hasText;
    }

    // Check for node selection (images, videos, etc.)
    if ('node' in selection && selection.node) {
      return true;
    }

    return false;
  }, [
    selection,
    selectionKey,
    tiptapEditor,
    isMobile,
    sessionLive,
    isAiWidgetModalOpen,
    submittedSelection,
  ]);

  const visible = expanded || showTooltip;

  const referenceElement = useMemo(
    () => ({
      getBoundingClientRect: () => {
        if (!tiptapEditor || !selection) {
          return new DOMRect(0, 0, 0, 0);
        }
        const { view } = tiptapEditor;
        const { from, to } = selection;
        return posToDOMRect(view, from, to);
      },
    }),
    [selection, tiptapEditor]
  );

  const [boxElement, setBoxElement] = useState<HTMLDivElement | null>(null);

  // While expanded, freeze the anchor to the pill's on-screen position at the
  // moment the prompt opened (see createExpandedAnchor). This both keeps the
  // prompt glued to the Aria avatar the user saw — even when the pill had been
  // flipped or shifted away from the selection — and prevents a click
  // elsewhere in the editor from moving the ProseMirror selection (and this
  // reference) before the click-outside handler below gets a chance to close
  // the panel, which produced a visible reposition-then-close flash.
  const frozenAnchorRef = React.useRef<ExpandedAnchor | null>(null);
  if (!expanded) {
    frozenAnchorRef.current = null;
  } else if (!frozenAnchorRef.current) {
    frozenAnchorRef.current = createExpandedAnchor(referenceElement, boxElement);
  }
  const expandedAnchor = expanded ? frozenAnchorRef.current : null;
  const activeReferenceElement = expandedAnchor?.reference ?? referenceElement;

  const expandedBelow = expandedAnchor?.side === 'bottom';
  const anchorOffset = expandedAnchor?.offset ?? SELECTION_OFFSET;

  const middleware = useMemo(() => {
    if (expanded) {
      return [
        // A pill-anchored reference already carries the pill's 8px offset from
        // the selection; only the raw-selection fallback needs it re-applied.
        offset(anchorOffset),
        // No flip while expanded: the panel must always render right next to the
        // Aria icon, on the side of the frozen anchor line it opened at, growing
        // away from it as its content grows — never jumping to the other side.
        // Shifting stays on: the icon and the panel share this one floating box,
        // so a clamp moves both together and the panel stays glued to the icon.
        // The limiter guards the horizontal axis only: when the ~464px assembly
        // (avatar + 420px panel) outgrows a narrow viewport's width, `shift`'s
        // clamp collapses to the padding origin and would teleport the prompt
        // away from the avatar — limitShift caps that travel at the anchor's own
        // extent instead. The vertical axis must stay unlimited: the frozen
        // anchor is a zero-height rect, which collapses limitShift's vertical
        // band to nothing and would silently discard the clamp wixel's
        // crossAxis padding asks for (top bar / bottom drawer) — the prompt has
        // to ride those edges while the stage scrolls, like the collapsed pill.
        shift({
          ...getShiftOptions(environment, boundary),
          limiter: limitShift({ crossAxis: false }),
        }),
      ];
    }
    return [
      offset(anchorOffset),
      shift(getShiftOptions(environment, boundary)),
      boundary ? flip({ boundary }) : flip(),
      ...(boundary ? [hide({ strategy: 'escaped' as const, boundary })] : []),
    ];
  }, [environment, boundary, expanded, anchorOffset]);

  const {
    x,
    y,
    isPositioned,
    refs: { setReference, setFloating },
    elements,
    update,
    strategy,
    middlewareData,
  } = useFloating({
    // When the pill sat below the selection (flip/shift had moved it there),
    // the prompt opens below too and grows downward — the avatar never jumps
    // back to the top side.
    placement: expandedBelow ? 'bottom-start' : 'top-start',
    middleware,
  });

  useAnimationPausedAutoUpdate({
    reference: elements.reference,
    floating: elements.floating,
    update,
  });

  // One stable callback: an inline `ref={el => …}` is a new identity every
  // commit, so React would detach (null) and re-attach the box every time.
  const setBoxRef = useCallback(
    (el: HTMLDivElement | null) => {
      setFloating(el);
      setBoxElement(el);
    },
    [setFloating]
  );

  useEffect(() => {
    setReference(activeReferenceElement);
  }, [setReference, activeReferenceElement]);

  const handleClick = useCallback(() => {
    if (!tiptapEditor || !modalService) {
      return;
    }
    openInlineAIModal({ editor: tiptapEditor, modalService });
  }, [tiptapEditor, modalService]);

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        handleClick();
      }
    },
    [handleClick]
  );

  const handleExpandedKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === 'Escape') {
        dismissTyping();
      }
    },
    [dismissTyping]
  );

  // FocusTrap reads its options once, on mount — which happens when `expanded`
  // flips true. Recomputing per render would also re-snapshot activeElement
  // long after the trap stopped reading it.
  const focusTrapOptions = useMemo(
    () => ({
      returnFocusOnDeactivate: false,
      fallbackFocus: document.activeElement as HTMLElement,
    }),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [expanded]
  );

  const selectionSnapshot = showTooltip ? selectionKey : null;

  const [introExpanded, setIntroExpanded] = useState(true);
  const [suppressIntroTransition, setSuppressIntroTransition] = useState(false);

  useLayoutEffect(() => {
    if (!selectionSnapshot) {
      setSuppressIntroTransition(false);
      return;
    }
    setIntroExpanded(true);
    setSuppressIntroTransition(true);
  }, [selectionSnapshot]);

  useEffect(() => {
    if (!selectionSnapshot) {
      return;
    }

    let cancelled = false;
    let innerRafId = 0;
    let collapseTimeoutId: number | undefined;

    const outerRafId = requestAnimationFrame(() => {
      innerRafId = requestAnimationFrame(() => {
        if (cancelled) {
          return;
        }
        setSuppressIntroTransition(false);
        collapseTimeoutId = window.setTimeout(() => {
          if (!cancelled) {
            setIntroExpanded(false);
          }
        }, HOLD_EXPANDED_MS);
      });
    });

    return () => {
      cancelled = true;
      cancelAnimationFrame(outerRafId);
      cancelAnimationFrame(innerRafId);
      if (collapseTimeoutId !== undefined) {
        window.clearTimeout(collapseTimeoutId);
      }
    };
  }, [selectionSnapshot]);

  // The suppression is scoped to the exact range that was submitted, so it lifts as
  // soon as the selection moves; dropping the store entry at that point is what lets
  // a later re-selection of that same range get its pill back.
  useEffect(() => {
    if (submittedSelection && submittedSelection !== selectionKey) {
      clearSubmittedSelection();
    }
  }, [submittedSelection, selectionKey, clearSubmittedSelection]);

  // Don't render if not visible or no portal
  if (!visible || !portal) {
    return null;
  }

  // `isPositioned` (not a falsy x/y): computePosition is async, so the box would
  // otherwise get one painted frame at the document origin before the first
  // position lands — and 0,0 is a legitimate result, not a "not yet" marker.
  const isHidden = middlewareData.hide?.escaped || (!isPositioned && !jsdomMode);

  const toolbarZ = zIndexService?.getZIndex('TOOLBAR');
  const suggestionStackZIndex: React.CSSProperties['zIndex'] =
    typeof toolbarZ === 'number'
      ? `var(--ricos-internal-suggestion-z-index, ${toolbarZ})`
      : 'var(--ricos-internal-suggestion-z-index, 5100)';
  const zIndex = expanded ? zIndexService?.getZIndex('DIALOG') : suggestionStackZIndex;

  const interactionProps = expanded
    ? { onKeyDown: handleExpandedKeyDown }
    : {
        onClick: handleClick,
        onKeyDown: handleKeyDown,
        role: 'button',
        tabIndex: 0,
        'aria-label': tooltipLabel,
      };

  const tooltip = (
    // ClickOutside stays mounted in both modes so the element tree (and the
    // Aria avatar's React instance) is preserved across collapsed<->expanded.
    <ClickOutside onClickOutside={expanded ? dismissTyping : NOOP}>
      <div
        ref={setBoxRef}
        className={classNames(
          style.aiSelectionTooltip,
          expanded && style.expanded,
          // expandedBelow is derived from the frozen anchor, which is null
          // unless expanded.
          expandedBelow && style.expandedBelow,
          !expanded && introExpanded && style.introExpanded,
          !expanded && suppressIntroTransition && style.noIntroTransition
        )}
        style={{
          position: strategy,
          left: x ?? 0,
          top: y ?? 0,
          zIndex,
          scale: 'var(--reverse-zoom-ratio, 1)',
          display: isHidden ? 'none' : 'flex',
        }}
        data-hook={INLINE_AI_SELECTION_TOOLTIP}
        {...interactionProps}
      >
        <span className={style.icon} aria-hidden>
          <AriaAvatarIcon />
        </span>
        {expanded && invocationId ? (
          <FocusManager
            focusTrapOptions={focusTrapOptions}
            jsdomMode={jsdomMode}
            active={!isHidden}
            preventScroll
          >
            <div className={style.panel} style={{ inlineSize: INLINE_AI_PANEL_WIDTH }}>
              {boxElement && (
                <UiComponentsProvider containerEl={boxElement}>
                  <InlineAiTypingPanel invocationId={invocationId} />
                </UiComponentsProvider>
              )}
            </div>
          </FocusManager>
        ) : (
          <span className={style.label} aria-hidden>
            <span className={style.labelText}>{tooltipLabel}</span>
          </span>
        )}
      </div>
    </ClickOutside>
  );

  return ReactDOM.createPortal(tooltip, portal);
};
