import classNames from 'classnames';
import React from 'react';

import { AiIcon } from './ai-icon.js';
import classes from './toolbar-button-scss.js';

export const ToolbarButton: React.FC<{ toggle: () => void; showLabel: boolean }> = ({
  toggle,
  showLabel,
}) => {
  return (
    <span
      className={classNames(classes.button, {
        [classes.buttonWithLabel]: showLabel,
      })}
      onClick={toggle}
    >
      <AiIcon /> {/*showLabel && t('AIPlugin_ToolbarButton_Text')*/}
    </span>
  );
};
