import { IconButton, Text } from '@wix/design-system';
import { ChevronDown, ChevronUp } from '@wix/wix-ui-icons-common/lazy';
import React from 'react';

import {
  INLINE_AI_PAGER,
  INLINE_AI_PAGER_NEXT_BUTTON,
  INLINE_AI_PAGER_PREV_BUTTON,
} from './data-hooks.js';

export type PagerProps = {
  total: number;
  current: number;
  onPrev: () => void;
  onNext: () => void;
};

export const Pager = ({ total, current, onPrev, onNext }: PagerProps) => {
  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 0 }} data-hook={INLINE_AI_PAGER}>
      <IconButton
        className="ai-region-button"
        size="tiny"
        priority="tertiary"
        skin="standard"
        onClick={() => {
          onPrev();
        }}
        dataHook={INLINE_AI_PAGER_PREV_BUTTON}
      >
        <ChevronUp />
      </IconButton>
      <Text size="small">
        {current + 1}/{total}
      </Text>
      <IconButton
        dataHook={INLINE_AI_PAGER_NEXT_BUTTON}
        className="ai-region-button"
        size="tiny"
        priority="tertiary"
        skin="standard"
        onClick={() => {
          onNext();
        }}
      >
        <ChevronDown />
      </IconButton>
    </div>
  );
};
