import type { RicosDocument, RicosDocumentNode } from './../ricos-schema/next-schema/index.js';
import { logInvariant } from './../_shared/log-invariant.js';

import type { AiMessage, AiMessageInsert, AiMessageReplace } from './types.js';

// We can't use ricos fixer for non-root level AI messages, so we
// convert every non-root level AI message to a root one, by using its parent node from original document.
// In some cases those messages will merge into one if their root node is the same
export const mergeNonRootAiMessages = (
  document: RicosDocument,
  messages: AiMessage[]
): AiMessage[] => {
  return messages.reduce<AiMessage[]>((acc, message) => {
    if (message.type === 'text' || message.type === 'theme' || message.isRootLevel) {
      acc.push(message);
      return acc;
    }
    const referenceNodeId = message.type === 'insert' ? message.after : message.from;
    if (!referenceNodeId) {
      logInvariant(new Error('Reference node id is missing in non-root level AI message'));
      acc.push(message);
      return acc;
    }

    const rootNodeId = findParentNodeId(document.nodes, referenceNodeId);

    if (!rootNodeId) {
      logInvariant(
        new Error(`Parent node not found for non-root level AI message ${referenceNodeId}`)
      );
      acc.push(message);
      return acc;
    }

    const existingMessageIndex = acc.findIndex(msg => {
      if (msg.type === 'replace') {
        return !!msg.nodes.find(node => node.id === rootNodeId);
      }
      return false;
    });

    if (existingMessageIndex === -1) {
      const rootNode = document.nodes.find(node => node.id === rootNodeId)!;
      const rootedMessage: AiMessage = {
        type: 'replace',
        from: rootNodeId,
        to: rootNodeId,
        nodes:
          message.type === 'replace'
            ? replaceChildrenDeep([rootNode], message)
            : insertChildrenDeep([rootNode], message),
        isRootLevel: true,
        completed: message.completed,
        viewBefore: message.viewBefore,
        originalNodesRef: {},
      };
      acc.push(rootedMessage);
      return acc;
    }
    const existingMessage = acc[existingMessageIndex] as AiMessageReplace;
    acc[existingMessageIndex] = {
      ...existingMessage,
      nodes:
        message.type === 'replace'
          ? replaceChildrenDeep(existingMessage.nodes, message)
          : insertChildrenDeep(existingMessage.nodes, message),
    };

    return acc;
  }, []);
};

const findParentNodeId = (nodes: RicosDocumentNode[], nodeId: string): string | undefined => {
  for (const node of nodes) {
    if (node.id === nodeId) {
      return node.id;
    }
    if ('nodes' in node && node.nodes && findParentNodeId(node.nodes, nodeId)) {
      return node.id;
    }
  }
  return undefined;
};

const replaceChildrenDeep = (
  children: RicosDocumentNode[],
  message: AiMessageReplace
): RicosDocumentNode[] => {
  const nodeFromIndex = children.findIndex(child => child.id === message.from);
  if (nodeFromIndex !== -1) {
    const nodeToIndex = children.findIndex(child => child.id === message.to, nodeFromIndex);
    if (nodeToIndex === -1) {
      logInvariant(new Error('Node `to` index not found in replace message among siblings'));
    }
    return [
      ...children.slice(0, nodeFromIndex),
      ...message.nodes,
      ...children.slice(nodeToIndex + 1),
    ];
  }
  return children.map(child => {
    if ('nodes' in child && child.nodes) {
      return {
        ...child,
        nodes: replaceChildrenDeep(child.nodes, message),
      } as RicosDocumentNode;
    }
    return child;
  });
};

const insertChildrenDeep = (
  children: RicosDocumentNode[],
  message: AiMessageInsert
): RicosDocumentNode[] => {
  const nodeAfterIndex = children.findIndex(child => child.id === message.after);
  if (nodeAfterIndex !== -1) {
    return [
      ...children.slice(0, nodeAfterIndex + 1),
      ...message.nodes,
      ...children.slice(nodeAfterIndex + 1),
    ];
  }
  return children.map(child => {
    if ('nodes' in child && child.nodes) {
      return {
        ...child,
        nodes: insertChildrenDeep(child.nodes, message),
      } as RicosDocumentNode;
    }
    return child;
  });
};
