import type { Dispatch, SetStateAction } from 'react';
import * as React from 'react';

import { PluginsContext, RicosContext } from './../ricos-context/index.js';
import { useOrchestrator } from './../ricos-context/orchestrator-context.js';
import { useModalState } from './../ricos-modals/modal-service-provider.js';
import type { RicosOrchestrator } from './../ricos-orchestrator/ricos-orchestrator.js';
import type { EditorPlugins } from './../ricos-plugins/index.js';
import { logInvariant } from './../_shared/log-invariant.js';
import type { SelectorContextValue } from './../_shared/use-context-selector.js';
import { useContextSelectorWithValue } from './../_shared/use-context-selector.js';

import { CursorContext } from './cursor-context.js';
import type { CursorState } from './cursor-context.js';
import { useExecutePrompt } from './execute-prompt.js';
import type { InlineAiContextType } from './inline-ai-context.js';
import { InlineAiContext } from './inline-ai-context.js';
import { hasKeepablePartialMessages } from './keepable-partial-messages.js';
import type { PagerAPI } from './pager-api.js';
import { getPagerAPI } from './pager-api.js';
import type {
  AiMessage,
  InlineAiAnchorProps,
  InlineAiFullState,
  InlineAiPluginConfig,
  InlineAiState,
} from './types.js';
import {
  DEFAULT_TYPING_STATE,
  INLINE_AI_MODAL_ID,
  INLINE_AI_PLUGIN_TYPE,
  shouldTooltipHostTyping,
} from './types.js';

const INITIAL_STATE: InlineAiFullState = {
  invocations: {},
};

export const InlineAiContextProvider: React.FC<{
  children: React.ReactNode;
  plugins: EditorPlugins;
}> = ({ children, plugins }) => {
  const [inlineAiState, setInlineAiState] = React.useState<InlineAiFullState>(INITIAL_STATE);
  const cursorAnchorRef = React.useRef<HTMLSpanElement>(null);
  const [cursorState, setCursorStateRaw] = React.useState<CursorState>({
    showCursor: false,
    label: null,
  });
  const setCursorState = React.useCallback((state: CursorState) => setCursorStateRaw(state), []);

  const orchestrator = useOrchestrator();
  const inlineAiPluginConfig = plugins.getConfig(INLINE_AI_PLUGIN_TYPE) as InlineAiPluginConfig;

  const value: [InlineAiFullState, Dispatch<SetStateAction<InlineAiFullState>>] = [
    inlineAiState,
    setInlineAiState,
  ];

  return (
    <CursorContext.Provider value={{ cursorAnchorRef, cursorState, setCursorState }}>
      <InlineAiContext.Provider
        value={value}
        onSelectorContextValue={x => {
          orchestrator.inlineAiStateSelectorContextValue = x;
        }}
      >
        <SetupExecutePrompt
          orchestrator={orchestrator}
          aiProjectId={inlineAiPluginConfig.aiProjectId}
          useWixelWidgets={inlineAiPluginConfig.useWixelWidgets}
        />
        {children}
      </InlineAiContext.Provider>
    </CursorContext.Provider>
  );
};

// Separate component to set up executePrompt (needs hooks)
const SetupExecutePrompt: React.FC<{
  orchestrator: RicosOrchestrator;
  aiProjectId?: string;
  useWixelWidgets?: boolean;
}> = ({ orchestrator, aiProjectId, useWixelWidgets }) => {
  const executePrompt = useExecutePrompt(aiProjectId, useWixelWidgets);
  if (orchestrator.inlineAiService) {
    orchestrator.inlineAiService.executePrompt = executePrompt;
  } else {
    logInvariant(new Error('Inline AI service is not available'));
  }
  return null;
};

// Config values (interceptInlinePrompt, theme callbacks, generatingLabel, …)
// are read from here at the point of use instead of being threaded through
// component props — every call site passes the identical config-derived value.
export const useInlineAiPluginConfig = (): InlineAiPluginConfig =>
  (React.useContext(PluginsContext)?.getConfig(INLINE_AI_PLUGIN_TYPE) ??
    {}) as InlineAiPluginConfig;

export type InlineAiApi = {
  state: InlineAiState | undefined;
  setState: React.Dispatch<React.SetStateAction<InlineAiState>>;
  pagerAPI: PagerAPI | undefined;
  stop: (arg: { headless: boolean; keepChanges?: boolean }) => void;
  triggerPreview: () => void;
  /**
   * Records the selection a submitted prompt acted on, so the selection tooltip's
   * pill stays down over it — see InlineAiFullState.submittedSelection.
   */
  setSubmittedSelection: (selectionKey: string | null) => void;
};

export const toClosed: (s: InlineAiState) => InlineAiState = s =>
  s.type === 'closed'
    ? s
    : {
        type: 'closed',
        messages: 'messages' in s ? s.messages : [],
        chunks: 'chunks' in s ? s.chunks : [],
        prompt: 'prompt' in s ? s.prompt : '',
      };

/**
 * The state of one invocation, defaulting a missing slice to 'typing'.
 *
 * Nothing writes the initial typing state — it is only ever the `defaultValue`
 * handed to useInlineAiState — so a just-opened invocation has no entry at all.
 * Every reader and writer of a session has to apply the same default or they
 * disagree about whether an untouched prompt exists.
 */
export const resolveInvocationState = (
  state: InlineAiFullState,
  invocationId: string
): InlineAiState => state.invocations[invocationId] ?? DEFAULT_TYPING_STATE;

/**
 * Records (or clears, with `null`) the selection a submitted prompt acted on. See
 * InlineAiFullState.submittedSelection. Returning `prevState` untouched when nothing
 * moves is what lets AiSelectionTooltip clear this from an effect without looping.
 */
export const withSubmittedSelection = (
  prevState: InlineAiFullState,
  submittedSelection: string | null
): InlineAiFullState =>
  prevState.submittedSelection === (submittedSelection ?? undefined)
    ? prevState
    : { ...prevState, submittedSelection: submittedSelection ?? undefined };

/**
 * AiSelectionTooltip's two visibility flags: `expanded` says the tooltip paints the prompt
 * input, `sessionLive` says it must not paint the collapsed pill.
 *
 * Both read the same `sessionState`, which is what keeps them from disagreeing. If they were
 * computed from sources that update in different commits, a dismissal would leave a commit
 * where neither holds — and the tooltip's box, along with the Aria avatar inside it, would
 * unmount and replay its fade. `hostedByTooltip` comes from the modal service and so can
 * change independently, but only when the modal itself opens or closes — and then
 * `sessionState` is undefined anyway, which is the same case as "no session".
 */
export const deriveSessionFlags = (
  hostedByTooltip: boolean,
  sessionState: InlineAiState | undefined
): { expanded: boolean; sessionLive: boolean } => ({
  expanded: hostedByTooltip && sessionState?.type === 'typing',
  sessionLive: sessionState !== undefined && sessionState.type !== 'closed',
});

export const computeStopTransition = (
  s: InlineAiState,
  { headless, keepChanges }: { headless: boolean; keepChanges?: boolean }
): InlineAiState => {
  if (s.type === 'pending' || s.type === 'streaming') {
    const prompt = s.prompt;
    const messages = 'messages' in s ? s.messages : [];
    const chunks = 'chunks' in s ? s.chunks : [];
    if (keepChanges && hasKeepablePartialMessages(messages)) {
      return { type: 'closed' as const, messages, chunks, prompt };
    }
    return headless
      ? {
          type: 'error' as const,
          error: { message: 'Cancelled by user', applicationErrorCode: 'USER_CANCELLED' },
          messages,
          chunks,
          prompt,
        }
      : { type: 'typing' as const, value: prompt };
  }
  return s;
};

export const useInlineAiStateWithSelectorContextValue = (
  selectorContextValue: SelectorContextValue<InlineAiContextType>,
  invocationId: string,
  defaultValue: InlineAiState | undefined
): InlineAiApi => {
  const [stateSlice, setState] = useContextSelectorWithValue(
    selectorContextValue,
    (
      ctx
    ): [
      InlineAiState | undefined,
      React.Dispatch<React.SetStateAction<InlineAiFullState>> | undefined,
    ] => [ctx?.[0]?.invocations?.[invocationId], ctx?.[1]],
    (a, b) => a[0] === b[0]
  );
  // Memoized because consumers put this setter in their own useCallback deps
  // (e.g. AiSelectionTooltip's dismissTyping, which is a ClickOutside handler
  // prop): an unstable identity re-registers those listeners every render.
  // Declared before the guard below so the hook stays unconditional.
  const setStateSlice = React.useCallback(
    (newState: React.SetStateAction<InlineAiState>) =>
      setState?.(prevState => {
        const currentInvocationState = prevState.invocations[invocationId] ?? defaultValue;
        const nextInvocationState =
          typeof newState === 'function' ? newState(currentInvocationState) : newState;
        return {
          ...prevState,
          invocations: {
            ...prevState.invocations,
            [invocationId]: nextInvocationState,
          },
        };
      }),
    [setState, invocationId, defaultValue]
  );

  const setSubmittedSelection = React.useCallback(
    (selectionKey: string | null) =>
      setState?.(prevState => withSubmittedSelection(prevState, selectionKey)),
    [setState]
  );

  if (!setState) {
    throw new Error('useInlineAiApi must be used within an InlineAiContextProvider');
  }

  const state = stateSlice ?? defaultValue;

  const stop = ({ headless, keepChanges }: { headless: boolean; keepChanges?: boolean }) => {
    setStateSlice(s => computeStopTransition(s, { headless, keepChanges }));
  };

  // Trigger preview state externally (e.g., when 'undo' is clicked after AI application)
  const triggerPreview = () => {
    setStateSlice((s: InlineAiState): InlineAiState => {
      if (s.type !== 'closed') {
        return s;
      }
      const actionableMessages = s.messages.filter(
        m => m.type === 'insert' || m.type === 'replace'
      );
      if (actionableMessages.length === 0) {
        return s;
      }
      return {
        type: 'preview' as const,
        messages: s.messages,
        activeMessageIndex: s.messages.findLastIndex(m => m.type !== 'text'),
        chunks: s.chunks,
        prompt: s.prompt,
      };
    });
  };

  return {
    state,
    setState: setStateSlice,
    stop,
    triggerPreview,
    setSubmittedSelection,
    pagerAPI:
      state?.type !== 'preview'
        ? undefined
        : getPagerAPI(
            state.messages,
            state.activeMessageIndex,
            (index: number) => {
              setStateSlice(prev =>
                prev && prev.type === 'preview' ? { ...prev, activeMessageIndex: index } : prev
              );
            },
            (arg: React.SetStateAction<AiMessage[]>) => {
              setStateSlice(prev =>
                prev && prev.type === 'preview'
                  ? { ...prev, messages: typeof arg === 'function' ? arg(prev.messages) : arg }
                  : prev
              );
            }
          ),
  };
};

export const useInlineAiState = (
  invocationId: string,
  defaultValue: InlineAiState
): Omit<InlineAiApi, 'state'> & { state: InlineAiState } => {
  const context = React.useContext(
    InlineAiContext as unknown as React.Context<SelectorContextValue<InlineAiContextType>>
  );
  if (!context) {
    throw new Error('useInlineAiApi must be used within an InlineAiContextProvider');
  }
  // @ts-expect-error
  return useInlineAiStateWithSelectorContextValue(context, invocationId, defaultValue);
};

export type AnchoredInlineAiSession = {
  /** The published session's invocation, whether or not the tooltip hosts it. */
  invocationId: string | undefined;
  /** The tooltip should paint the prompt input for this session right now. */
  expanded: boolean;
  /** An inline-AI session is live, so the collapsed pill must stay suppressed. */
  sessionLive: boolean;
  /** Moves the published session to `closed`; the modal then closes itself. */
  dismiss: () => void;
  /** See InlineAiFullState.submittedSelection — the pill stays down over this range. */
  submittedSelection: string | undefined;
  /** Lifts that suppression, once the selection has moved off the submitted range. */
  clearSubmittedSelection: () => void;
};

/**
 * AiSelectionTooltip's whole view of the inline-AI world.
 *
 * The anchored session is not something the modal has to announce: the modal service already
 * holds the opening's `componentProps` in a reactive store, and `invocationId` +
 * `anchorToSelection` are stamped there by openInlineAIModal. Reading them back is both
 * simpler than a publish/subscribe hop and strictly earlier — the store entry exists before
 * AiModalNg mounts, so there is no frame where the pill is up with no prompt input.
 *
 * Both flags then read *through* `invocations[invocationId]`, so an opening whose session has
 * already reached 'closed' is inert even though its modal is still up.
 */
export const useAnchoredInlineAiSession = (): AnchoredInlineAiSession => {
  const context = React.useContext(
    InlineAiContext as unknown as React.Context<SelectorContextValue<InlineAiContextType>>
  );
  if (!context) {
    throw new Error('useAnchoredInlineAiSession must be used within an InlineAiContextProvider');
  }

  // Selects the componentProps object itself, never a derived value: useModalState compares
  // with Object.is, and this object is built once per opening (ModalService.openModal) and
  // preserved by setModalRef, so it is stable for the modal's lifetime.
  const anchorProps = useModalState(
    s => s[INLINE_AI_MODAL_ID]?.componentProps as InlineAiAnchorProps | undefined
  );
  const { isMobile } = React.useContext(RicosContext) || {};
  const { enableSelectionTooltip } = useInlineAiPluginConfig();

  const invocationId = anchorProps?.invocationId;
  const hostedByTooltip =
    Boolean(enableSelectionTooltip) && shouldTooltipHostTyping(anchorProps, isMobile);

  const [sessionState, setState, submittedSelection] = useContextSelectorWithValue(
    context,
    ctx => {
      const fullState = ctx?.[0];
      return [
        invocationId && fullState ? resolveInvocationState(fullState, invocationId) : undefined,
        ctx?.[1],
        fullState?.submittedSelection,
      ] as const;
    },
    // A fresh tuple every render, so it has to be compared by content —
    // useContextSelectorWithValue dispatches during render on inequality.
    (a, b) => a[0] === b[0] && a[1] === b[1] && a[2] === b[2]
  );

  // Stable identity: this ends up as ClickOutside's handler prop, whose effect
  // re-registers its document listeners whenever the handler changes.
  const dismiss = React.useCallback(() => {
    if (!invocationId) {
      return;
    }
    setState?.(prevState => ({
      ...prevState,
      invocations: {
        ...prevState.invocations,
        // resolveInvocationState, not a raw lookup: dismissing an untouched prompt
        // (opened and escaped without typing) still has to write a 'closed' slice,
        // or the modal never sees the transition that closes it.
        [invocationId]: toClosed(resolveInvocationState(prevState, invocationId)),
      },
    }));
  }, [setState, invocationId]);

  // Stable for the same reason as `dismiss`: AiSelectionTooltip puts this in an
  // effect's dep list.
  const clearSubmittedSelection = React.useCallback(
    () => setState?.(prevState => withSubmittedSelection(prevState, null)),
    [setState]
  );

  return {
    invocationId,
    ...deriveSessionFlags(hostedByTooltip, sessionState),
    dismiss,
    submittedSelection,
    clearSubmittedSelection,
  };
};
