import type { AiMessage } from './types.js';

/** Same rule as modal `messageIsAcceptable` for applying edits — not preview-only. */
const messageIsAcceptableForApply = (m: AiMessage): boolean =>
  (m.type === 'insert' || m.type === 'replace') && !m.viewBefore;

/**
 * True when stop-with-keep should commit: real insert/replace with non-empty nodes.
 * Empty placeholder ops would strip selection without adding generated content.
 */
export const hasKeepablePartialMessages = (messages: AiMessage[]): boolean =>
  messages.some(m => {
    if (m.type !== 'insert' && m.type !== 'replace') {
      return false;
    }
    return messageIsAcceptableForApply(m) && m.nodes.length > 0;
  });
