import type { RicosDocumentNode } from './../ricos-schema/next-schema/index.js';

export const filterOutExternalNodes = (nodes: RicosDocumentNode[]): RicosDocumentNode[] =>
  nodes
    .filter(n => n.type !== 'EXTERNAL')
    .map(n => {
      const newNode = { ...n };
      if ('nodes' in newNode && newNode.nodes) {
        newNode.nodes = filterOutExternalNodes(newNode.nodes);
      }
      return newNode;
    });
