import { SkeletonGroup, SkeletonRectangle } from '@wix/design-system';
import React from 'react';

import type { ImageNode } from './../ricos-schema/next-schema/index.js';

export const ImagePlaceholder = ({ node }: { node: ImageNode }) => {
  const containerRef = React.useRef<HTMLDivElement>(null);

  const containerWidth = containerRef.current?.offsetWidth;
  const imageAspectRatio =
    node.imageData?.image.width && node.imageData?.image?.height
      ? node.imageData.image.width / node.imageData.image.height
      : 16 / 9;

  const calculatedHeight = containerWidth ? containerWidth / imageAspectRatio : 200;

  return (
    <div style={{ position: 'relative' }} ref={containerRef}>
      <SkeletonGroup skin="light">
        <SkeletonRectangle width={'100%'} height={calculatedHeight + 'px'} />
      </SkeletonGroup>
    </div>
  );
};

