import React, { useContext } from 'react';

import { RicosContext } from './../ricos-context/index.js';

import { AriaAvatarIcon } from './aria-avatar-icon.js';
import classes from './aria-surface-row-scss.js';

/**
 * Puts the Aria avatar beside the modal-hosted prompt input (the non-anchored
 * typing flows), mirroring the row the expanded AiSelectionTooltip builds around
 * the same panel for the selection-anchored flows.
 *
 * Nothing here may set `clip-path`, `filter`, `mask`, `opacity` < 1 or
 * `mix-blend-mode`: each forms a backdrop root, which would confine the prompt
 * input's `backdrop-filter` to this row's own content and silently paint no glass
 * at all (see ai-selection-tooltip.scss's `.expanded`, which has to say
 * `clip-path: none` for exactly this reason).
 */
export const AriaSurfaceRow: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { isMobile } = useContext(RicosContext) || {};

  return (
    <div className={classes.row}>
      {/* Desktop only: the avatar's 44px gutter is too much of a phone viewport. */}
      {!isMobile && (
        <span className={classes.icon} aria-hidden>
          <AriaAvatarIcon />
        </span>
      )}
      <div className={classes.content}>{children}</div>
    </div>
  );
};
