import { Button, Text } from '@wix/design-system';
import { MagicWandSparkles } from '@wix/wix-ui-icons-common/lazy';
import classNames from 'classnames';
import type { FC } from 'react';
import React, { useEffect, useRef, useState } from 'react';

import classes from './pending-widget-placeholder-scss.js';

export const PendingWidgetPlaceholder = ({ node }: any) => {
  const hasError = false; // props.node.attrs.error?.type === 'error';
  const containerRef = useRef<HTMLDivElement>(null);
  const [videoCount, setVideoCount] = useState(6);

  const tokenCount = (node.externalData?.htmlData?.html?.split(/\s+/).length ?? 0) * 1.5;
  const image = node.externalData?.type === 'IMAGE';
  useEffect(() => {
    const container = containerRef.current;
    if (!container) {
      return;
    }

    const calculateVideoCount = () => {
      const containerWidth = container.offsetWidth;
      // Base calculation: 1 video per 100px width, minimum 3 videos
      const calculatedCount = Math.max(3, Math.floor(containerWidth / 100));
      setVideoCount(calculatedCount);
    };

    calculateVideoCount();

    const resizeObserver = new ResizeObserver(calculateVideoCount);
    resizeObserver.observe(container);

    // // Start typewriter effect after container animation completes (0.8s)
    // const animationTimer = setTimeout(() => {
    //   setIsAnimationComplete(true);
    // }, 800);

    return () => {
      resizeObserver.disconnect();
      // clearTimeout(animationTimer);
    };
  }, []);

  const renderVideos = () => {
    const videos = [];
    for (let i = 0; i < videoCount; i++) {
      const rotation = (i * 90) % 360;
      videos.push(<PixelatedVideo key={i} style={{ transform: `rotate(${rotation}deg)` }} />);
    }
    return videos;
  };

  return (
    <div
      data-suggestion-placeholder=""
      ref={containerRef}
      className={classNames(classes.container, {
        [classes.errorContainer]: hasError,
      })}
    >
      {hasError ? (
        <>
          <div
            className={classes.textContainer}
            style={{ '--wds-button-border-radius-tiny': '8px' } as React.CSSProperties}
          >
            <div className={classes.iconContainer}>
              <SmileIcon />
            </div>
            <Text size="medium" weight="normal">
              Whoops... Something went wrong
            </Text>
            <Button skin="dark" size="small" onClick={() => {}}>
              Try again
            </Button>
          </div>
          <div className={classes.squaresContainer}>
            <SquaresIcon />
          </div>
        </>
      ) : (
        <>
          {renderVideos()}

          <div className={classes.textContainer}>
            <div className={classes.iconContainer}>
              <MagicWandSparkles />
            </div>
            <div className={classes.textContent}>
              <Text size="medium" weight="normal">
                {tokenCount >= 1 && (
                  <>
                    Tokens poured:{' '}
                    <span
                      style={{
                        fontFamily: 'monospace',
                      }}
                    >
                      {tokenCount.toFixed(0)}
                    </span>
                  </>
                )}
                {image && 'Generating image'}
              </Text>
            </div>
          </div>
        </>
      )}
    </div>
  );
};

const PixelatedVideo: FC<{ style?: React.CSSProperties }> = ({ style }) => {
  const regular =
    'https://static.parastorage.com/services/media-design-creator/5c8bd5808b6b2809627044d9647adafff2553cee0be9af052fbb13c7/media/pixelated-xlarge.90aa8356.webm';
  const retina =
    'https://static.parastorage.com/services/media-design-creator/dc28d74e33766ad88bb9b6d024b375e4d3a4bbaa82fae00d2d6bcfd0/media/pixelated-xlarge-retina.bd56976d.webm';

  return (
    // oxlint-disable-next-line jsx-a11y/media-has-caption
    <video
      tabIndex={-1}
      aria-hidden="true"
      loop
      autoPlay
      muted
      style={{
        transformOrigin: 'center center',
        height: '140px',
        objectFit: 'cover',
        objectPosition: 'center center',
        aspectRatio: '1 / 1',
        flex: 1,
        opacity: 0.6,
        ...style,
      }}
    >
      <source src={regular} type="video/webm" media="(max-resolution: 191dpi)" />
      <source src={retina} type="video/webm" media="(min-resolution: 192dpi)" />
    </video>
  );
};

