import type { ModalService } from './../ricos-modals/modal-service.js';
import type { TiptapEditor } from './../ricos-types/index.js';
import type { ModalPositioning } from './../ricos-types/modal-types.js';
import { getFakeReferenceElement } from './../_shared/pos-to-dom-rect.js';

import { AiModalNg } from './modal.js';
import type { InlineAiAnchorProps } from './types.js';
import { INLINE_AI_MODAL_ID } from './types.js';

type OpenInlineAIModalOptions = {
  editor: TiptapEditor;
  modalService: ModalService;
  positioning?: ModalPositioning;
};

export const openInlineAIModal = ({
  editor,
  modalService,
  positioning = {},
}: OpenInlineAIModalOptions) => {
  if (modalService.isModalOpen(INLINE_AI_MODAL_ID)) {
    return modalService.getModal(INLINE_AI_MODAL_ID);
  }

  const resolvedPositioning: ModalPositioning = {
    referenceElement: getFakeReferenceElement(editor),
    placement: 'bottom',
    ...positioning,
  };

  const componentProps: InlineAiAnchorProps = {
    // Generated here (not inside AiModalNg) so the selection tooltip can
    // read it off the modal config and share the typing state slice.
    invocationId: crypto.randomUUID(),
    // 'bottom' placement = the selection-based flows (icon click,
    // space-over-selection, quick actions); see InlineAiAnchorProps.
    anchorToSelection: resolvedPositioning.placement === 'bottom',
  };

  return modalService.openModal({
    id: INLINE_AI_MODAL_ID,
    Component: AiModalNg,
    componentProps,
    layout: 'manual',
    type: 'exclusive',
    positioning: resolvedPositioning,
    returnFocusToEditor: false,
  });
};
