import { Loader } from '@wix/design-system';
import React from 'react';

import type { HtmlNode } from './../ricos-schema/next-schema/index.js';
import { INIT_WIDTH } from './../plugin-html/defaults.js';

import style from './html-placeholder-scss.js';

export const HtmlPlaceholder = ({ node }: { node: HtmlNode }) => {
  const html = node.htmlData.html || '';

  return (
    <div
      className={style.container}
      style={{
        maxWidth: (node.htmlData.containerData?.width?.custom || INIT_WIDTH) + 'px',
      }}
    >
      <div className={style.overlay}>
        <div style={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
          <Loader size="tiny" />
          Writing code...
        </div>
      </div>
      <div className={style.innerContainer}>{formatWithLineNumbers(html)}</div>
    </div>
  );
};

const formatWithLineNumbers = (inputHtml: string): string => {
  const allLines = inputHtml
    .split('\n')
    .map((line, index) => `${(index + 1).toString().padStart(4, ' ')}: ${line}`);
  const lastLines = allLines.slice(-30);
  return lastLines.join('\n');
};

export const HtmlPlaceholderMocked = () => {
  const lines = 'sample code\nline two'.split('\n');

  const [currentCuttof, setCurrentCutoff] = React.useState(1);

  React.useEffect(() => {
    if (currentCuttof < lines.length) {
      const timeout = setInterval(() => {
        setCurrentCutoff(s => s + 3);
      }, 500);
      return () => clearInterval(timeout);
    }
  }, []);

  const sampleHtml = lines.slice(0, currentCuttof).join('\n');

  return (
    <div style={{ margin: '20px auto', width: '826px' }}>
      <HtmlPlaceholder node={{ type: 'html', htmlData: { html: sampleHtml } } as any} />
    </div>
  );
};
