import React, { useContext, useEffect, useRef } from 'react';

import { EditorContext } from './../ricos-context/editor-context.js';
import { ModalServiceContext, UploadContext, useDevService } from './../ricos-context/index.js';
import type { RicosDocument } from './../ricos-schema/next-schema/index.js';
import { handleFileUpload } from './../_shared/handle-file-upload.js';
import { logInvariant } from './../_shared/log-invariant.js';
import type { Attachment } from './../_shared/pm-node-types.js';
import type { PromptInputAreaRef } from './../_shared/prompt-input-area/prompt-input-area.js';
import {
  PromptInputArea,
  WidgetPromptInputArea,
} from './../_shared/prompt-input-area/prompt-input-area.js';
import { useWixInstanceService } from './../_shared/request-service-provider/wix-instance-context.js';
import { useEditorProps } from './../_shared/some-editor-props-context.js';

import { INLINE_AI_MODAL_ROOT, INLINE_AI_PROMPT_INPUT } from './data-hooks.js';
import { useExecutePrompt } from './execute-prompt.js';
import {
  toClosed,
  useInlineAiPluginConfig,
  useInlineAiState,
} from './inline-ai-context-provider.js';
import { DEFAULT_TYPING_STATE, toSelectionKey } from './types.js';

export type InlineAiTypingPanelProps = {
  invocationId: string;
};

// The inline-AI prompt input (typing state), self-contained so it can be
// hosted either by the modal's FloatingContainer (non-anchored flows) or by
// the expanded selection tooltip (anchored flows in wixel). State is shared
// with the modal through InlineAiContext, keyed by invocationId.
export const InlineAiTypingPanel: React.FC<InlineAiTypingPanelProps> = ({ invocationId }) => {
  const { getPublicCommands, adapter } = useContext(EditorContext);
  const modalService = useContext(ModalServiceContext);
  const { uploadService } = useContext(UploadContext) || {};
  const devService = useDevService();
  const wixInstance = useWixInstanceService();
  const editorProps = useEditorProps();
  const pluginConfig = useInlineAiPluginConfig();
  const { interceptInlinePrompt, getCurrentTheme, onThemeChange } = pluginConfig;

  const { state, setState, setSubmittedSelection } = useInlineAiState(
    invocationId,
    DEFAULT_TYPING_STATE
  );
  const executePrompt = useExecutePrompt(pluginConfig.aiProjectId, pluginConfig.useWixelWidgets);
  const SelectedPromptInputArea = pluginConfig.useWixelWidgets
    ? WidgetPromptInputArea
    : PromptInputArea;

  // Every attachment mutation is the same shape: ignore it unless we're still
  // typing, then swap in a new list.
  const updateAttachments = (update: (attachments: Attachment[]) => Attachment[]) =>
    setState(s => (s.type !== 'typing' ? s : { ...s, attachments: update(s.attachments ?? []) }));

  const ref = useRef<PromptInputAreaRef>(null);
  useEffect(() => {
    // focus input and place cursor at the end of text
    ref.current?.focus();
  }, []);

  if (state.type !== 'typing') {
    return null;
  }

  const attachments = state.attachments ?? [];

  const handleFileUploadFn = async () => {
    if (!uploadService) {
      return;
    }

    await handleFileUpload({
      pluginId: 'inline-ai',
      services: {
        uploadService,
        devService,
        wixInstance,
        editorProps,
        modals: modalService,
      },
      callbacks: {
        onLoadingStart: (attachment: Attachment) => {
          updateAttachments(list => [...list, attachment]);
        },
        onSuccess: (attachmentId: string, attachment: Attachment) => {
          updateAttachments(list =>
            list.some(a => a.id === attachmentId)
              ? list.map(a => (a.id === attachmentId ? attachment : a))
              : [...list, attachment]
          );
        },
        onError: (attachmentId, attachment) => {
          updateAttachments(list =>
            list.map(a =>
              a.id === attachmentId
                ? { id: attachmentId, status: 'error', file: a.file, error: attachment.error }
                : a
            )
          );
        },
      },
    });
  };

  return (
    <div data-hook={INLINE_AI_MODAL_ROOT}>
      <SelectedPromptInputArea
        ref={ref}
        dataHook={INLINE_AI_PROMPT_INPUT}
        onChange={x =>
          setState(prev => ({
            type: 'typing',
            value: x,
            attachments: 'attachments' in prev ? prev.attachments : [],
          }))
        }
        onSubmit={() => {
          const selection = getPublicCommands().getSelectionSlice() ?? [];
          const files = attachments
            .filter(a => a.status === 'ok')
            .map(a => ({
              fileUrl: a.file.url,
              mimeType: a.file.type,
              fileName: a.file.name ?? '',
            }));
          const interceptResult = interceptInlinePrompt?.(
            state.value,
            selection,
            files,
            invocationId
          );

          if (interceptResult === 'replace') {
            // The interceptor already started a headless inline-AI run, which reopens
            // this same modal id in headless mode. Closing here would unmount the
            // headless modal before its `closed` effect applies the streamed changes.
            return;
          }

          if (interceptResult === 'stop') {
            // The prompt has been handed off (in wixel it goes to the Aria chat
            // panel), so the selection tooltip's pill must not pop straight back up
            // over the selection the user just acted on — see
            // InlineAiFullState.submittedSelection.
            const pmSelection = adapter?.tiptapEditor?.state.selection;
            setSubmittedSelection(pmSelection ? toSelectionKey(pmSelection) : null);
            // The modal closes itself off this transition (its 'closed' effect);
            // closing it here too would only split the change across two commits
            // for anyone deriving from both.
            setState(toClosed);
            return;
          }

          if (!executePrompt) {
            logInvariant(new Error('Inline AI service not available'));
            return;
          }

          executePrompt({
            document: getPublicCommands().getContent() as RicosDocument,
            prompt: state.value,
            selection,
            getCurrentTheme,
            invocationId,
            onThemeChange,
            files,
          });
        }}
        onCancel={() => {}}
        value={state.value}
        zIndex={1000}
        maxLength={1000}
        attachments={attachments}
        onRemoveAttachment={id => {
          updateAttachments(list => list.filter(a => a.id !== id));
        }}
        fileUploadFn={uploadService ? handleFileUploadFn : undefined}
      />
    </div>
  );
};
