import React, { useEffect, useRef } from 'react';

import { AiAssistantAvatar, type AstroRef } from './../bundled-dependencies/ai-assistant-avatar.js';

// The Aria avatar that sits beside every inline-AI surface. `show()` is not
// optional: the package renders its wrapper at `opacity: 0` until it is called,
// and only on mount — which is why hosts keep this component mounted rather than
// re-creating it per state (a remount replays the fade).
export const AriaAvatarIcon: React.FC = () => {
  const avatarRef = useRef<AstroRef>(null);

  useEffect(() => {
    avatarRef.current?.show();
  }, []);

  return <AiAssistantAvatar ref={avatarRef} />;
};
