import { SparklesSmall } from '@wix/wix-ui-icons-common/lazy';
import React from 'react';

import type { ModalService } from './../ricos-modals/modal-service.js';
import type { RicosDocumentNode } from './../ricos-schema/next-schema/index.js';
import type {
  EditorPluginCreator,
  ExtensionProps,
  ModalProps,
  RicosExtension,
  RicosExtensionConfig,
} from './../ricos-types/index.js';
import { Node_Type, quickActionsModalSections } from './../ricos-types/index.js';
import { getIsEditorEmpty } from './../_shared/get-is-editor-empty.js';
import { logInvariant } from './../_shared/log-invariant.js';
import { getFakeReferenceElement } from './../_shared/pos-to-dom-rect.js';
import { quickActionsPluginKey } from './../_shared/quick-actions-plugin-key.js';
import { isAlwaysVisible } from './../_shared/resolvers/is-always-visible.js';
import { TOP_LEVEL_NODES } from './../_shared/top-level-nodes.js';
import type { CommandProps, Editor } from './../tiptap/core/index.js';
import type { Node as ProsemirrorNode } from './../tiptap/pm/model.js';
import type { Selection } from './../tiptap/pm/state.js';
import { Plugin, PluginKey } from './../tiptap/pm/state.js';
import type { TiptapAdapterServices } from './../tiptap-editor/initialize-tiptap-adapter.js';
import { createRicosFunctionalExtension } from './../tiptap-extensions/index.js';

import { aiRegion } from './ai-region-extension.js';
import { AiSelectionTooltip } from './ai-selection-tooltip.js';
import { CursorContext } from './cursor-context.js';
import { InlineAiContextProvider } from './inline-ai-context-provider.js';
import { AiModalNg, StreamingCursor } from './modal.js';
import { openInlineAIModal } from './open-inline-ai-modal.js';
import { ToolbarButtonSmall } from './toolbar/toolbar-button-small.js';
import { ToolbarButton } from './toolbar/toolbar-button.js';
import { INLINE_AI_MODAL_ID, INLINE_AI_PLUGIN_TYPE } from './types.js';
import type { InlineAiPluginConfig, InlineAiService } from './types.js';

// Kept as a re-export for external importers (e.g. ricos-types'
// editor-plugin-options); the definition lives in types.ts.
export type { InlineAiPluginConfig } from './types.js';

declare module './../tiptap/core' {
  interface Commands<ReturnType> {
    inlineAi: {
      triggerInlineAi: (args: {
        invocationId?: string;
        headless?: boolean;
        prompt: string;
        selection: RicosDocumentNode[];
        modalConfig?: Omit<
          ModalProps['modalConfig'],
          'Component' | 'id' | 'componentProps' | 'layout'
        >;
        onDone?: (result: { type: 'error' } | { type: 'done' }) => void;
        acceptByDefault?: boolean;
        files?: { fileUrl: string; mimeType: string; fileName: string }[];
        traceParams?: Record<string, string>;
        systemPromptId?: string;
      }) => ReturnType;
    };
  }
}

export const pluginInlineAi: EditorPluginCreator<InlineAiPluginConfig> = config => {
  const inlinePromptEnabled = !config?.disableInlinePrompt;

  const GlobalComponents: React.FC = () => {
    const cursorCtx = React.useContext(CursorContext);
    return (
      <>
        {inlinePromptEnabled && config?.enableSelectionTooltip && <AiSelectionTooltip />}
        {cursorCtx?.cursorState.showCursor && <StreamingCursor />}
      </>
    );
  };

  return {
    config: { type: 'inlineAi' as const, ...config },
    type: INLINE_AI_PLUGIN_TYPE,
    Provider: InlineAiContextProvider,
    GlobalComponent: GlobalComponents,

    getQuickActions: () =>
      inlinePromptEnabled
        ? [
            {
              id: 'mainAI',
              title: 'QuickActionsPlugin_ActionTitle_InlineAI',
              icon: SparklesSmall,
              section: quickActionsModalSections.AI,
              tags: [' ', 'ai', 'write', 'automated'],
              command: ({ editor, modalService }) => {
                const { view } = editor;
                const rootLevelNodePosition = view.state.selection.$from.before(1);

                const nodeDOM = view.nodeDOM(rootLevelNodePosition);
                const referenceElement = nodeDOM instanceof Element ? nodeDOM : view.dom;

                editor.commands.setNodeSelection(rootLevelNodePosition);

                openInlineAIModal({
                  editor,
                  modalService,
                  positioning: {
                    referenceElement: {
                      getBoundingClientRect: () => referenceElement.getBoundingClientRect(),
                      focus: () => view.focus(),
                    },
                    placement: 'bottom',
                  },
                });
                return true;
              },
            },
          ]
        : [],
    exports: {
      modals: inlinePromptEnabled
        ? {
            INLINE_AI: (editor, services) =>
              openInlineAIModal({ editor, modalService: services.modals }),
          }
        : {},
    },
    textButtons: inlinePromptEnabled
      ? [
          {
            id: 'wix-rich-content-plugin-ai',
            type: 'modal',
            presentation: {
              dataHook: 'text-button-ai',
              tooltip: 'AIPlugin_ToolbarButton_Tooltip',
              component: (props: $TSFixMe) => <ToolbarButton {...props} showLabel />,
              icon: (props: $TSFixMe) => <ToolbarButtonSmall {...props} showLabel />, // Rendering in external toolbar
            },
            attributes: {
              visible: isAlwaysVisible,
            },
            command:
              ({ editor, modalService }) =>
              () => {
                const { view } = editor;

                const rootLevelNodePosition = view.state.selection.$from.before(1);
                const nodeDOM = view.nodeDOM(rootLevelNodePosition);
                const referenceElement = nodeDOM instanceof Element ? nodeDOM : view.dom;
                openInlineAIModal({
                  editor,
                  modalService,
                  positioning: {
                    placement: 'top',
                    referenceElement: {
                      getBoundingClientRect: () => referenceElement.getBoundingClientRect(),
                      focus: () => view.focus(),
                    },
                  },
                });
                return true;
              },
          },
        ]
      : [],
    tiptapExtensions: [
      aiRegion,
      createRicosFunctionalExtension({
        name: 'inline-ai',
        type: 'extension',
        groups: [],
        placeholder: {
          priority: 200,
          predicate: ({ doc, selection, node, pos, editor, isMobile }) => {
            if (!inlinePromptEnabled || isMobile) {
              return false;
            }
            const $pos = doc.resolve(pos);

            const isEditorEmpty = getIsEditorEmpty(doc);

            if (isEditorEmpty && !editor.isFocused) {
              return false;
            }

            const isEmptyTopLevelParagraph =
              (TOP_LEVEL_NODES as readonly string[]).includes($pos.parent.type.name) &&
              !selection.$head.nodeBefore &&
              !selection.$head.nodeAfter &&
              node.type.name === Node_Type.PARAGRAPH;

            const isEmpty = !node.isLeaf && !node.childCount;

            const isSelected =
              selection.from - 1 === pos && selection.to + 1 === pos + node.nodeSize;

            return isEmptyTopLevelParagraph && isEmpty && isSelected;
          },
          content: 'InlineAiPlugin_EditorPlaceholder',
        },
        reconfigure: (
          config: RicosExtensionConfig<any, any>,
          _extensions: RicosExtension[],
          _ricosProps: ExtensionProps,
          _settings: Record<string, unknown>,
          services: TiptapAdapterServices
        ) => {
          return {
            ...config,
            addOptions: () => {
              return { services };
            },
          };
        },

        createExtensionConfig() {
          return {
            name: 'inline-ai',
            priority: 110,

            addProseMirrorPlugins() {
              return [
                new Plugin({
                  key: new PluginKey('inline-ai'),
                  props: {
                    handleKeyDown: (view, event) => {
                      if (!inlinePromptEnabled) {
                        return false;
                      }

                      const modalService: ModalService = this.options.services.modals;
                      const spacePressed = event.key === ' ';

                      if (!spacePressed || this.options.services.context.isMobile) {
                        return false;
                      }

                      if (event.shiftKey || event.altKey) {
                        return false;
                      }

                      if (!view.state.selection.empty) {
                        openInlineAIModal({ editor: this.editor, modalService });
                        return true;
                      }

                      const quickActionsState = quickActionsPluginKey.getState(view.state);

                      const $from = view.state.selection.$from;
                      // Walk past any wrapper nodes (CARD → CARD_CONTENT → …) to
                      // land on the actual top-level content block under the cursor.
                      let depth = 1;
                      while (
                        depth < $from.depth &&
                        (TOP_LEVEL_NODES as readonly string[]).includes($from.node(depth).type.name)
                      ) {
                        depth += 1;
                      }
                      const rootLevelNodeUnderCursor = $from.node(depth);
                      const rootLevelNodePosition = $from.before(depth);

                      const quickActionsTrigger =
                        quickActionsState &&
                        quickActionsState.active &&
                        quickActionsState.text === '/';

                      if (quickActionsTrigger) {
                        view.dispatch(
                          view.state.tr.delete(
                            quickActionsState.range.from,
                            quickActionsState.range.to
                          )
                        );
                      }

                      if (
                        predicate({
                          doc: view.state.doc,
                          selection: view.state.selection,
                          node: rootLevelNodeUnderCursor,
                          pos: rootLevelNodePosition,
                          editor: this.editor,
                        })
                      ) {
                        // Get DOM reference to the root level node for positioning
                        const nodeDOM = view.nodeDOM(rootLevelNodePosition);
                        const referenceElement = nodeDOM instanceof Element ? nodeDOM : view.dom;

                        this.editor.commands.setNodeSelection(rootLevelNodePosition);

                        // Through openInlineAIModal, not a bare openModal, so this opening
                        // gets an invocationId stamped into its componentProps like every
                        // other one — that id is how AiSelectionTooltip finds the session
                        // and keeps its pill down while the prompt is up. The 'overlay'
                        // placement keeps anchorToSelection false, so the modal paints the
                        // prompt itself here.
                        openInlineAIModal({
                          editor: this.editor,
                          modalService,
                          positioning: {
                            referenceElement: {
                              getBoundingClientRect: () => referenceElement.getBoundingClientRect(),
                              focus: () => view.focus(),
                            },
                            placement: 'overlay',
                          },
                        });
                        return true;
                      }
                      if (quickActionsTrigger) {
                        // Uses openInlineAIModal's defaults (fake reference + 'bottom'),
                        // which also stamp the selection-anchor props.
                        openInlineAIModal({ editor: this.editor, modalService });
                        return true;
                      }
                    },
                  },
                }),
              ];
            },

            addCommands() {
              return {
                triggerInlineAi:
                  ({
                    prompt,
                    selection,
                    modalConfig,
                    acceptByDefault = false,
                    invocationId,
                    headless,
                    onDone,
                    files,
                    traceParams,
                    systemPromptId,
                  }: {
                    prompt: string;
                    selection: RicosDocumentNode[];
                    modalConfig?: Omit<
                      ModalProps['modalConfig'],
                      'Component' | 'id' | 'componentProps' | 'layout' | 'enableDrag'
                    >;
                    onDone?: (result: { type: 'error' } | { type: 'done' }) => void;
                    acceptByDefault?: boolean;
                    invocationId?: string;
                    headless?: boolean;
                    files?: {
                      fileUrl: string;
                      mimeType: string;
                      fileName: string;
                    }[];
                    traceParams?: Record<string, string>;
                    systemPromptId?: string;
                  }) =>
                  ({ tr, dispatch }: CommandProps) => {
                    const modalService: ModalService = this.options.services.modals;
                    const inlineAiService: InlineAiService = this.options.services.inlineAi;

                    const _invocationId = invocationId || crypto.randomUUID();
                    if (!inlineAiService.executePrompt) {
                      logInvariant(new Error('Inline AI service is not available'));
                      return true;
                    }
                    const document = this.options.services.schema.getContent();
                    inlineAiService.executePrompt({
                      prompt,
                      selection,
                      invocationId: _invocationId,
                      files,
                      onThemeChange: config?.onThemeChange,
                      getCurrentTheme: config?.getCurrentTheme,
                      document,
                      traceParams,
                      systemPromptId,
                    });
                    modalService.openModal({
                      id: INLINE_AI_MODAL_ID,
                      Component: AiModalNg,
                      componentProps: {
                        acceptByDefault,
                        invocationId: _invocationId,
                        headless,
                        onDone,
                      },
                      type: 'exclusive',
                      layout: 'manual',
                      positioning: {
                        referenceElement: getFakeReferenceElement(this.editor),
                      },
                      returnFocusToEditor: false,
                      ...modalConfig,
                    });

                    if (dispatch) {
                      dispatch(tr);
                    }

                    return true;
                  },
              };
            },
          };
        },
      }),
    ],
  };
};

const predicate = ({
  doc,
  selection,
  node,
  pos,
  editor,
}: {
  doc: ProsemirrorNode;
  node: ProsemirrorNode;
  selection: Selection;
  pos: number;
  editor: Editor;
}) => {
  const $pos = doc.resolve(pos);

  if (getIsEditorEmpty(doc) && !editor.isFocused) {
    return false;
  }

  const isEmptyTopLevelParagraph =
    (TOP_LEVEL_NODES as readonly string[]).includes($pos.parent.type.name) &&
    !selection.$head.nodeBefore &&
    !selection.$head.nodeAfter &&
    (node.type.name === Node_Type.PARAGRAPH || node.type.name === Node_Type.HEADING);

  const isEmpty = !node.isLeaf && !node.childCount;

  const isSelected = selection.from - 1 === pos && selection.to + 1 === pos + node.nodeSize;

  return isEmptyTopLevelParagraph && isEmpty && isSelected;
};
